window.KH_SURA(39, {"sura": "الزمر", "n": 39, "ayat": {"1": "تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ", "2": "إِنَّا أَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ", "3": "أَلَا لِلَّهِ الدِّينُ الْخَالِصُ وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لَا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ", "4": "لَوْ أَرَادَ اللَّهُ أَنْ يَتَّخِذَ وَلَدًا لَاصْطَفَى مِمَّا يَخْلُقُ مَا يَشَاءُ سُبْحَانَهُ هُوَ اللَّهُ الْوَاحِدُ الْقَهَّارُ", "5": "خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ يُكَوِّرُ اللَّيْلَ عَلَى النَّهَارِ وَيُكَوِّرُ النَّهَارَ عَلَى اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُسَمًّى أَلَا هُوَ الْعَزِيزُ الْغَفَّارُ", "6": "خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنْزَلَ لَكُمْ مِنَ الْأَنْعَامِ ثَمَانِيَةَ أَزْوَاجٍ يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ فِي ظُلُمَاتٍ ثَلَاثٍ ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ لَا إِلَهَ إِلَّا هُوَ فَأَنَّى تُصْرَفُونَ", "7": "إِنْ تَكْفُرُوا فَإِنَّ اللَّهَ غَنِيٌّ عَنْكُمْ وَلَا يَرْضَى لِعِبَادِهِ الْكُفْرَ وَإِنْ تَشْكُرُوا يَرْضَهُ لَكُمْ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى ثُمَّ إِلَى رَبِّكُمْ مَرْجِعُكُمْ فَيُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ", "8": "وَإِذَا مَسَّ الْإِنْسَانَ ضُرٌّ دَعَا رَبَّهُ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُ نِعْمَةً مِنْهُ نَسِيَ مَا كَانَ يَدْعُو إِلَيْهِ مِنْ قَبْلُ وَجَعَلَ لِلَّهِ أَنْدَادًا لِيُضِلَّ عَنْ سَبِيلِهِ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا إِنَّكَ مِنْ أَصْحَابِ النَّارِ", "9": "أَمَّنْ هُوَ قَانِتٌ آنَاءَ اللَّيْلِ سَاجِدًا وَقَائِمًا يَحْذَرُ الْآخِرَةَ وَيَرْجُو رَحْمَةَ رَبِّهِ قُلْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ", "10": "قُلْ يَاعِبَادِ الَّذِينَ آمَنُوا اتَّقُوا رَبَّكُمْ لِلَّذِينَ أَحْسَنُوا فِي هَذِهِ الدُّنْيَا حَسَنَةٌ وَأَرْضُ اللَّهِ وَاسِعَةٌ إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ", "11": "قُلْ إِنِّي أُمِرْتُ أَنْ أَعْبُدَ اللَّهَ مُخْلِصًا لَهُ الدِّينَ", "12": "وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ الْمُسْلِمِينَ", "13": "قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ", "14": "قُلِ اللَّهَ أَعْبُدُ مُخْلِصًا لَهُ دِينِي", "15": "فَاعْبُدُوا مَا شِئْتُمْ مِنْ دُونِهِ قُلْ إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا ذَلِكَ هُوَ الْخُسْرَانُ الْمُبِينُ", "16": "لَهُمْ مِنْ فَوْقِهِمْ ظُلَلٌ مِنَ النَّارِ وَمِنْ تَحْتِهِمْ ظُلَلٌ ذَلِكَ يُخَوِّفُ اللَّهُ بِهِ عِبَادَهُ يَاعِبَادِ فَاتَّقُونِ", "17": "وَالَّذِينَ اجْتَنَبُوا الطَّاغُوتَ أَنْ يَعْبُدُوهَا وَأَنَابُوا إِلَى اللَّهِ لَهُمُ الْبُشْرَى فَبَشِّرْ عِبَادِ", "18": "الَّذِينَ يَسْتَمِعُونَ الْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُ أُولَئِكَ الَّذِينَ هَدَاهُمُ اللَّهُ وَأُولَئِكَ هُمْ أُولُو الْأَلْبَابِ", "19": "أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ الْعَذَابِ أَفَأَنْتَ تُنْقِذُ مَنْ فِي النَّارِ", "20": "لَكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ غُرَفٌ مِنْ فَوْقِهَا غُرَفٌ مَبْنِيَّةٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ وَعْدَ اللَّهِ لَا يُخْلِفُ اللَّهُ الْمِيعَادَ", "21": "أَلَمْ تَرَ أَنَّ اللَّهَ أَنْزَلَ مِنَ السَّمَاءِ مَاءً فَسَلَكَهُ يَنَابِيعَ فِي الْأَرْضِ ثُمَّ يُخْرِجُ بِهِ زَرْعًا مُخْتَلِفًا أَلْوَانُهُ ثُمَّ يَهِيجُ فَتَرَاهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُ حُطَامًا إِنَّ فِي ذَلِكَ لَذِكْرَى لِأُولِي الْأَلْبَابِ", "22": "أَفَمَنْ شَرَحَ اللَّهُ صَدْرَهُ لِلْإِسْلَامِ فَهُوَ عَلَى نُورٍ مِنْ رَبِّهِ فَوَيْلٌ لِلْقَاسِيَةِ قُلُوبُهُمْ مِنْ ذِكْرِ اللَّهِ أُولَئِكَ فِي ضَلَالٍ مُبِينٍ", "23": "اللَّهُ نَزَّلَ أَحْسَنَ الْحَدِيثِ كِتَابًا مُتَشَابِهًا مَثَانِيَ تَقْشَعِرُّ مِنْهُ جُلُودُ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَى ذِكْرِ اللَّهِ ذَلِكَ هُدَى اللَّهِ يَهْدِي بِهِ مَنْ يَشَاءُ وَمَنْ يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ", "24": "أَفَمَنْ يَتَّقِي بِوَجْهِهِ سُوءَ الْعَذَابِ يَوْمَ الْقِيَامَةِ وَقِيلَ لِلظَّالِمِينَ ذُوقُوا مَا كُنْتُمْ تَكْسِبُونَ", "25": "كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ فَأَتَاهُمُ الْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ", "26": "فَأَذَاقَهُمُ اللَّهُ الْخِزْيَ فِي الْحَيَاةِ الدُّنْيَا وَلَعَذَابُ الْآخِرَةِ أَكْبَرُ لَوْ كَانُوا يَعْلَمُونَ", "27": "وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِنْ كُلِّ مَثَلٍ لَعَلَّهُمْ يَتَذَكَّرُونَ", "28": "قُرْآنًا عَرَبِيًّا غَيْرَ ذِي عِوَجٍ لَعَلَّهُمْ يَتَّقُونَ", "29": "ضَرَبَ اللَّهُ مَثَلًا رَجُلًا فِيهِ شُرَكَاءُ مُتَشَاكِسُونَ وَرَجُلًا سَلَمًا لِرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ", "30": "إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ", "31": "ثُمَّ إِنَّكُمْ يَوْمَ الْقِيَامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ", "32": "فَمَنْ أَظْلَمُ مِمَّنْ كَذَبَ عَلَى اللَّهِ وَكَذَّبَ بِالصِّدْقِ إِذْ جَاءَهُ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِلْكَافِرِينَ", "33": "وَالَّذِي جَاءَ بِالصِّدْقِ وَصَدَّقَ بِهِ أُولَئِكَ هُمُ الْمُتَّقُونَ", "34": "لَهُمْ مَا يَشَاءُونَ عِنْدَ رَبِّهِمْ ذَلِكَ جَزَاءُ الْمُحْسِنِينَ", "35": "لِيُكَفِّرَ اللَّهُ عَنْهُمْ أَسْوَأَ الَّذِي عَمِلُوا وَيَجْزِيَهُمْ أَجْرَهُمْ بِأَحْسَنِ الَّذِي كَانُوا يَعْمَلُونَ", "36": "أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ وَيُخَوِّفُونَكَ بِالَّذِينَ مِنْ دُونِهِ وَمَنْ يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ هَادٍ", "37": "وَمَنْ يَهْدِ اللَّهُ فَمَا لَهُ مِنْ مُضِلٍّ أَلَيْسَ اللَّهُ بِعَزِيزٍ ذِي انْتِقَامٍ", "38": "وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلْ أَفَرَأَيْتُمْ مَا تَدْعُونَ مِنْ دُونِ اللَّهِ إِنْ أَرَادَنِيَ اللَّهُ بِضُرٍّ هَلْ هُنَّ كَاشِفَاتُ ضُرِّهِ أَوْ أَرَادَنِي بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَاتُ رَحْمَتِهِ قُلْ حَسْبِيَ اللَّهُ عَلَيْهِ يَتَوَكَّلُ الْمُتَوَكِّلُونَ", "39": "قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ", "40": "مَنْ يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُقِيمٌ", "41": "إِنَّا أَنْزَلْنَا عَلَيْكَ الْكِتَابَ لِلنَّاسِ بِالْحَقِّ فَمَنِ اهْتَدَى فَلِنَفْسِهِ وَمَنْ ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا أَنْتَ عَلَيْهِمْ بِوَكِيلٍ", "42": "اللَّهُ يَتَوَفَّى الْأَنْفُسَ حِينَ مَوْتِهَا وَالَّتِي لَمْ تَمُتْ فِي مَنَامِهَا فَيُمْسِكُ الَّتِي قَضَى عَلَيْهَا الْمَوْتَ وَيُرْسِلُ الْأُخْرَى إِلَى أَجَلٍ مُسَمًّى إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ", "43": "أَمِ اتَّخَذُوا مِنْ دُونِ اللَّهِ شُفَعَاءَ قُلْ أَوَلَوْ كَانُوا لَا يَمْلِكُونَ شَيْئًا وَلَا يَعْقِلُونَ", "44": "قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ ثُمَّ إِلَيْهِ تُرْجَعُونَ", "45": "وَإِذَا ذُكِرَ اللَّهُ وَحْدَهُ اشْمَأَزَّتْ قُلُوبُ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ وَإِذَا ذُكِرَ الَّذِينَ مِنْ دُونِهِ إِذَا هُمْ يَسْتَبْشِرُونَ", "46": "قُلِ اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِي مَا كَانُوا فِيهِ يَخْتَلِفُونَ", "47": "وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا مَا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لَافْتَدَوْا بِهِ مِنْ سُوءِ الْعَذَابِ يَوْمَ الْقِيَامَةِ وَبَدَا لَهُمْ مِنَ اللَّهِ مَا لَمْ يَكُونُوا يَحْتَسِبُونَ", "48": "وَبَدَا لَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "49": "فَإِذَا مَسَّ الْإِنْسَانَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَاهُ نِعْمَةً مِنَّا قَالَ إِنَّمَا أُوتِيتُهُ عَلَى عِلْمٍ بَلْ هِيَ فِتْنَةٌ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", "50": "قَدْ قَالَهَا الَّذِينَ مِنْ قَبْلِهِمْ فَمَا أَغْنَى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ", "51": "فَأَصَابَهُمْ سَيِّئَاتُ مَا كَسَبُوا وَالَّذِينَ ظَلَمُوا مِنْ هَؤُلَاءِ سَيُصِيبُهُمْ سَيِّئَاتُ مَا كَسَبُوا وَمَا هُمْ بِمُعْجِزِينَ", "52": "أَوَلَمْ يَعْلَمُوا أَنَّ اللَّهَ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يُؤْمِنُونَ", "53": "قُلْ يَاعِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ", "54": "وَأَنِيبُوا إِلَى رَبِّكُمْ وَأَسْلِمُوا لَهُ مِنْ قَبْلِ أَنْ يَأْتِيَكُمُ الْعَذَابُ ثُمَّ لَا تُنْصَرُونَ", "55": "وَاتَّبِعُوا أَحْسَنَ مَا أُنْزِلَ إِلَيْكُمْ مِنْ رَبِّكُمْ مِنْ قَبْلِ أَنْ يَأْتِيَكُمُ الْعَذَابُ بَغْتَةً وَأَنْتُمْ لَا تَشْعُرُونَ", "56": "أَنْ تَقُولَ نَفْسٌ يَاحَسْرَتَا عَلَى مَا فَرَّطْتُ فِي جَنْبِ اللَّهِ وَإِنْ كُنْتُ لَمِنَ السَّاخِرِينَ", "57": "أَوْ تَقُولَ لَوْ أَنَّ اللَّهَ هَدَانِي لَكُنْتُ مِنَ الْمُتَّقِينَ", "58": "أَوْ تَقُولَ حِينَ تَرَى الْعَذَابَ لَوْ أَنَّ لِي كَرَّةً فَأَكُونَ مِنَ الْمُحْسِنِينَ", "59": "بَلَى قَدْ جَاءَتْكَ آيَاتِي فَكَذَّبْتَ بِهَا وَاسْتَكْبَرْتَ وَكُنْتَ مِنَ الْكَافِرِينَ", "60": "وَيَوْمَ الْقِيَامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى اللَّهِ وُجُوهُهُمْ مُسْوَدَّةٌ أَلَيْسَ فِي جَهَنَّمَ مَثْوًى لِلْمُتَكَبِّرِينَ", "61": "وَيُنَجِّي اللَّهُ الَّذِينَ اتَّقَوْا بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ السُّوءُ وَلَا هُمْ يَحْزَنُونَ", "62": "اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ", "63": "لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ وَالَّذِينَ كَفَرُوا بِآيَاتِ اللَّهِ أُولَئِكَ هُمُ الْخَاسِرُونَ", "64": "قُلْ أَفَغَيْرَ اللَّهِ تَأْمُرُونِّي أَعْبُدُ أَيُّهَا الْجَاهِلُونَ", "65": "وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ", "66": "بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ", "67": "وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ", "68": "وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَى فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ", "69": "وَأَشْرَقَتِ الْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ الْكِتَابُ وَجِيءَ بِالنَّبِيِّينَ وَالشُّهَدَاءِ وَقُضِيَ بَيْنَهُمْ بِالْحَقِّ وَهُمْ لَا يُظْلَمُونَ", "70": "وَوُفِّيَتْ كُلُّ نَفْسٍ مَا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ", "71": "وَسِيقَ الَّذِينَ كَفَرُوا إِلَى جَهَنَّمَ زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَتْلُونَ عَلَيْكُمْ آيَاتِ رَبِّكُمْ وَيُنْذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَذَا قَالُوا بَلَى وَلَكِنْ حَقَّتْ كَلِمَةُ الْعَذَابِ عَلَى الْكَافِرِينَ", "72": "قِيلَ ادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ", "73": "وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ", "74": "وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي صَدَقَنَا وَعْدَهُ وَأَوْرَثَنَا الْأَرْضَ نَتَبَوَّأُ مِنَ الْجَنَّةِ حَيْثُ نَشَاءُ فَنِعْمَ أَجْرُ الْعَامِلِينَ", "75": "وَتَرَى الْمَلَائِكَةَ حَافِّينَ مِنْ حَوْلِ الْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِيَ بَيْنَهُمْ بِالْحَقِّ وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ"}, "units": [{"aya": 2, "title": "معنى: {بالحق}", "mawsua": {"taliq": 5602, "masala": "معنى: {بالحق}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون معناه: متضمنا الحق", "ashab": "", "athar": []}, {"n": 2, "t": "أن يعني: الاستحقاق والوجوب، وشمول المنفعة للعالم في هدايتهم ودعوتهم إلى الله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5602, "mi": 1, "aya": 2, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 369 - 370", "qawl": "", "nass": "أن يكون معناه: متضمنا الحق", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 5, "title": "الأجل المسمى", "mawsua": {"taliq": 5603, "masala": "الأجل المسمى", "sigha": "زاد احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: أوقات مغيبها كل يوم وليلة", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: أوقات رجوعها إلى قوانينها؛ كل شهر في القمر، وكل سنة في الشمس", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5603, "mi": 1, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 372", "qawl": "", "nass": "أن يريد: أوقات مغيبها كل يوم وليلة", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 6, "title": "تأويل: ﴿يخلقكم في بطون أمهاتكم خلقا من بعد خلق﴾", "tabari": {"page": "20/165", "sarih": 0, "tarjih": "وأولى القولين في ذلك بالصواب، القول الذي قاله عكرمة ومجاهد ومن قال في ذلك مثل قولهما؛ لأن الله جل وعز أخبر أنه يخلقنا خلقا من بعد خلق في بطون أمهاتنا في ظلمات ثلاث، ولم يخبر أنه يخلقنا في بطون أمهاتنا من بعد خلقنا في ظهر آدم، وذلك نحو قوله: ﴿ولقد خلقنا الإنسان من سلالة من طين (١٢) ثم جعلناه نطفة في قرار مكين (١٣) ثم خلقنا النطفة علقة﴾ الآية [المؤمنون: ١٢ - ١٤].", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "﴿يخلقكم في بطون أمهاتكم خلقا من بعد خلق﴾. يقول تعالى ذكره: يبتدئ خلقكم أيها الناس في بطون أمهاتكم خلقا من بعد خلق. وذلك أنه يحدث فيها نطفة، ثم يجعلها علقة، ثم مضغة، ثم عظاما، ثم يكسو العظام لحما، ثم ينشئه خلقا آخر، تبارك الله ربنا وتعالى، فذلك خلقه إياه خلقا بعد خلق.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل معني ذلك: يخلقكم في بطون أمهاتكم من بعد خلقه إياكم في ظهر آدم. قالوا: فذلك هو الخلق من بعد الخلق", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [67152, 67162]}]}, "mawaqif": [{"taliq": 5605, "mi": 1, "aya": 6, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 165", "qawl": "الأول", "nass": "لأن الله -جل وعز- أخبر أنه يخلقنا خلقا من بعد خلق في بطون أمهاتنا في ظلمات ثلاث، ولم يخبر أنه يخلقنا في بطون أمهاتنا من بعد خلقنا في ظهر آدم، وذلك نحو قوله: {ولقد خلقنا الإنسان من سلالة من طين* ثم جعلناه نطفة في قرار مكين* ثم خلقنا النطفة علقة} الآية [المؤمنون: 12، 13، 14]", "qawaid": ["ظاهر الآية ولفظها", "القرآن والنظائر"], "tabi": ""}], "mushid": {"i": 1, "imgs": ["039_001_1.png"], "pages": [445], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5605, "masala": "معنى: {يخلقكم في بطون أمهاتكم خلقا من بعد خلق}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "يبتدئ خلقكم -أيها الناس- في بطون أمهاتكم خلقا من بعد خلق: نطفة، ثم علقة، ثم مضغة", "ashab": "", "athar": []}, {"n": 2, "t": "يخلقكم في بطون أمهاتكم من بعد خلقه إياكم في ظهر آدم", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها", "القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 6, "title": "معنى: {ثم جعل منها زوجها}", "mawsua": {"taliq": 5604, "masala": "معنى: {ثم جعل منها زوجها}", "sigha": "ذكر قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنها خلقت من ضلعه القصيري", "ashab": "", "athar": []}, {"n": 2, "t": "ونقله عن فرقة: أنها خلقت من نفس طين آدم عليه السلام، ثم رجح الأول قائلا: «والأول أصح». ولم يذكر مستندا", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5604, "mi": 1, "aya": 6, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 373", "qawl": "", "nass": "أنها خلقت من ضلعه القصيري", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 7, "title": "في تأويل قوله: ﴿إن تكفروا فإن الله غني عنكم ولا يرضى لعباده الكفر﴾", "tabari": {"page": "20/168", "sarih": 1, "tarjih": "والصواب من القول في ذلك ما قال جل ثناؤه: ﴿إن تكفروا﴾ بالله أيها الكفار به، ﴿فإن الله غني﴾ عن إيمانكم وعبادتكم إياه، ﴿ولا يرضى لعباده الكفر﴾. بمعنى: ولا يرضى لعباده أن يكفروا به، كما يقال: لست أحب الظلم، وإن أحببت أن يظلم فلان فلانا فيعاقب.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ذلك لخاص من الناس، ومعناه: إن تكفروا أيها المشركون بالله، فإن الله غني عنكم، ولا يرضى لعباده المؤمنين الذين أخلصهم لعبادته وطاعته - الكفر", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["السدي", "تابعي"]], "athar": [67166, 67168, 67172, 67174, 67177]}, {"n": 2, "t": "بل ذلك عام لجميع الناس، ومعناه: أيها الناس إن تكفروا، فإن الله غني عنكم، ولا يرضى لكم أن تكفروا به", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5607, "mi": 1, "aya": 7, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 169", "qawl": "", "nass": "ما قال الله -جل ثناؤه-: {إن تكفروا} بالله، أيها الكفار به، {فإن الله غني} عن إيمانكم وعبادتكم إياه، {ولا يرضى لعباده الكفر} بمعنى: ولا يرضى لعباده أن يكفروا به، كما يقال: لست أحب الظلم، وإن أحببت أن يظلم فلان فلانا فيعاقب", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5607, "mi": 1, "aya": 7, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 374 - 375", "qawl": "الأول", "nass": "هذه الآية مخاطبة للكفار الذين لم يرد الله أن يطهر قلوبهم، وعباده هم المؤمنون", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["039_002_1.png"], "pages": [445], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5607, "masala": "معنى: {إن تكفروا فإن الله غني عنكم ولا يرضى لعباده الكفر}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن ذلك خاص ببعض الناس، والمعنى: إن تكفروا -أيها المشركون- بالله فإن الله غني عنكم، ولا يرضى لعباده المؤمنين الذين أخلصهم لعبادته وطاعته الكفر", "ashab": "", "athar": []}, {"n": 2, "t": "أن ذلك عام لجميع الناس، والمعنى: أيها الناس، إن تكفروا فإن الله غني عنكم، ولا يرضى لكم أن تكفروا به", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 8, "title": "في المعنى الذي جعلوها فيه له أندادا", "tabari": {"page": "20/173", "sarih": 1, "tarjih": "وأولى القولين في ذلك بالصواب قول من قال: عني به أنه أطاع الشيطان في عبادة الأوثان، فجعل له الأوثان أندادا؛ لأن ذلك في سياق عتاب الله إياهم على عبادتها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "جعلوها له أندادا في طاعتهم إياهم في معاصى الله", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [67183, 67185, 67187]}, {"n": 2, "t": "عنى بذلك أنه عبد الأوثان، فجعلها لله أندادا في عبادتهم إياها", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5610, "mi": 1, "aya": 8, "alam": "ابن جرير", "fil": "ذكره", "kind": "نقل", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5610, "mi": 1, "aya": 8, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 173", "qawl": "الثاني", "nass": "لأن ذلك في سياق عتاب الله إياهم على عبادتها", "qawaid": ["السياق"], "tabi": ""}], "mushid": {"i": 3, "imgs": ["039_003_1.png"], "pages": [446], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 5610, "masala": "صفة جعلهم الشركاء لله أندادا", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "جعلوها له أندادا في طاعتهم إياهم في معاصي الله", "ashab": "السدي", "athar": [67187]}, {"n": 2, "t": "جعلوها لله أندادا في عبادتهم إياها", "ashab": "", "athar": []}]}, "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}, {"aya": 9, "title": "قراءة قوله تعالى: {أمن هو قانت آناء الليل}", "mawsua": {"taliq": 5611, "masala": "قراءة قوله تعالى: {أمن هو قانت آناء الليل}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أمن» بتخفيف الميم", "ashab": "", "athar": []}, {"n": 2, "t": "{أمن} بتشديد الميم، والمعنى: «أم من هو؟ ويقولون: إنما هي {أمن} استفهام اعترض في الكلام بعد كلام قد مضى، فجاء ب» أم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5611, "mi": 1, "aya": 9, "alam": "ابن جرير", "fil": "نقل", "kind": "نقل", "ref": "20/ 174 - 175 بتصرف", "qawl": "", "nass": "ولقراءتهم ذلك كذلك وجهان: أحدهما: أن يكون الألف في «أمن", "qawaid": [], "tabi": ""}, {"taliq": 5611, "mi": 1, "aya": 9, "alam": "ابن جرير", "fil": "وجهها", "kind": "توجيه", "ref": "20/ 175", "qawl": "", "nass": "فعلى هذا التأويل يجب أن يكون جواب الاستفهام متروكا من أجل أنه قد جرى الخبر عن فريق الكفر، وما أعد له في الآخرة، ثم أتبع الخبر عن فريق الإيمان، فعلم بذلك المراد، فاستغني بمعرفة السامع بمعناه من ذكره، إذ كان معقولا أن معناه: هذا أفضل أم هذا؟", "qawaid": [], "tabi": ""}, {"taliq": 5611, "mi": 1, "aya": 9, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 378", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5611, "mi": 1, "aya": 9, "alam": "ابن جرير", "fil": "ذكرهما", "kind": "نقل", "ref": "", "qawl": "الأول", "nass": "ولا يوقف -على هذا التأويل- على قوله سبحانه: {ويرجو رحمة ربه}", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5611, "mi": 1, "aya": 9, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 379", "qawl": "", "nass": "أم", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 10, "title": "في تأويل ذلك ﴿قل ياعباد الذين آمنوا اتقوا ربكم للذين أحسنوا في هذه الدنيا حسنة وأرض الله واسعة إنما يوفى﴾", "tabari": {"page": "20/178", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: للذين أطاعوا الله حسنة في هذه الدنيا. وقال: \"في\" من صلة \"حسنة\"، وجعل معنى الحسنة: الصحة والعافية", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [67211, 67225]}, {"n": 2, "t": "\"في\" من صلة \"أحسنوا\"، ومعنى الحسنة: الجنة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5613, "mi": 1, "aya": 10, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 381", "qawl": "الثاني", "nass": "وكان قياس قوله أن يكون {في هذه الدنيا} متأخرا، ويجوز تقديمه", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 5, "imgs": ["039_005_1.png"], "pages": [446], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5613, "masala": "معنى: «الحسنة»", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها الجنة والنعيم", "ashab": "", "athar": []}, {"n": 2, "t": "أنها العافية والطهور وولاية الله تعالى", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 18, "title": "معنى: {الذين يستمعون القول فيتبعون أحسنه}", "mawsua": {"taliq": 5619, "masala": "معنى: {الذين يستمعون القول فيتبعون أحسنه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه لا إله إلا الله", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الرجل يجلس مع القوم فيسمع كلامهم، فيعمل بالمحاسن ويحدث بها، ويكف عن المساوئ ولا يظهرها", "ashab": "", "athar": []}, {"n": 3, "t": "أنه طاعة الله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5619, "mi": 1, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 384", "qawl": "كتاب الله", "nass": "أي: إذا سمعوا الأقاويل وسمعوا القرآن اتبعوا القرآن", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 24, "title": "في صفة اتقاء هذا الضال بوجهه سوء العذاب", "tabari": {"page": "20/194", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هو أن يرمى به في جهنم مكبوبا على وجهه، فذلك اتقاؤه إياه", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [67336]}, {"n": 2, "t": "هو أن ينطلق به إلى النار مكتوفا، ثم يرمى به فيها، فأول ما تمس النار وجهه. وهذا قول يذكر عن ابن عباس من وجه كرهت ذكره؛ لضعف سنده ، وهذا أيضا مما ترك جوابه، استغناء بدلالة ما ذكر من الكلام عليه عنه. ومعنى الكلام: أفمن يتقي بوجهه سوء العذاب يوم القيامة خير، أم من ينعم في الجنان؟", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5623, "mi": 0, "aya": 24, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 194", "qawl": "ابن عباس", "nass": "وهذا قول يذكر عن ابن عباس من وجه كرهت ذكره؛ لضعف سنده", "qawaid": [], "tabi": ""}], "mushid": {"i": 6, "imgs": ["039_006_1.png"], "pages": [446], "n": 2, "rajih": [], "daif": [2], "match": true}, "tags": {"m": {}, "t": {"2": [["ابن جرير", "d"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 31, "title": "في تأويل ذلك ﴿ثم إنكم يوم القيامة عند ربكم تختصمون﴾", "tabari": {"page": "20/200", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: عنى بذلك: إنك يا محمد ستموت، وإنكم أيها الناس ستموتون، ثم إن جميعكم أيها الناس تختصمون عند ربكم؛ مؤمنكم وكافركم، ومحقوكم ومبطلوكم، وظالموكم ومظلوموكم، حتى يؤخذ لكل [من كل منكم] ممن لصاحبه قبله حق - حقه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى به اختصام المؤمنين والكافرين، واختصام المظلوم به والظالم", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["ابن زيد", "تابع التابعين"], ["عبد الله بن الزبير", "صحابي"]], "athar": [67380, 67386, 67390]}, {"n": 2, "t": "بل عني بذلك اختصام أهل الإسلام", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عمر", "صحابي"], ["إبراهيم", "تابعي"], ["أبي العالية", "تابعي"]], "athar": [67375, 67376, 67377, 67379, 67381, 67382]}]}, "mawaqif": [{"taliq": 5628, "mi": 1, "aya": 31, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 392", "qawl": "الأول", "nass": "ومن هذا قول علي:", "qawaid": [], "tabi": ""}, {"taliq": 5628, "mi": 1, "aya": 31, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 202", "qawl": "العموم", "nass": "جميعكم أيها الناس تختصمون عند ربكم، مؤمنكم وكافركم، ومحقوكم ومبطلوكم، وظالموكم ومظلوموكم، حتى يؤخذ لكل من كل منكم ممن لصاحبه قبله حق حقه", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 5628, "mi": 1, "aya": 31, "alam": "ابن عطية", "fil": "حكى", "kind": "نقل", "ref": "7/ 393", "qawl": "العموم", "nass": "أنه يختصم الروح مع الجسد في أن يذنب كل واحد منهما صاحبه، ويجعل المعصية في حيزه، فيحكم الله تعالى بشركتهما في ذلك", "qawaid": [], "tabi": ""}, {"taliq": 5628, "mi": 1, "aya": 31, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "12/ 126، 129", "qawl": "العموم", "nass": "هذه الآية وإن كان سياقها في المؤمنين والكافرين، وذكر الخصومة بينهم في الدار الآخرة، فإنها شاملة لكل متنازعين في الدنيا، فإنه تعاد عليهم الخصومة في الدار الآخرة", "qawaid": ["العموم"], "tabi": ""}], "mushid": {"i": 7, "imgs": ["039_007_1.png"], "pages": [446], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5628, "masala": "معنى هذه الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "عني بها اختصام المؤمنين والكافرين، والمظلوم والظالم", "ashab": "", "athar": []}, {"n": 2, "t": "عني بها اختصام أهل الإسلام", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [["ابن جرير", "رجّح العموم"], ["ابن كثير", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"], "ابن كثير": ["العموم"]}, "rulesD": {}}}, {"aya": 33, "title": "في الذي جاء بالصدق وصدق به، وما ذلك ﴿والذي جاء بالصدق وصدق به أولئك هم المتقون لهم ما يشاءون عند ربهم ذلك جزاء المحسنين﴾", "tabari": {"page": "20/204", "sarih": 1, "tarjih": "والصواب من القول في ذلك أن يقال: إن الله تعالى ذكره عنى بقوله: ﴿والذي جاء بالصدق وصدق به﴾. كل من دعا إلى توحيد الله، وتصديق رسوله، والعمل بما ابتعث به رسوله؛ من بين رسول الله وأتباعه والمؤمنين به، وأن يقال: الصدق هو القرآن، وشهادة أن لا إله إلا الله، والمصدق به المؤمنون بالقرآن، من جميع خلق الله كائنا من كان من نبي الله وأتباعه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "الذي جاء بالصدق رسول الله ﷺ، قالوا: والصدق الذي جاء به: لا إله الله إلا الله، والذي صدق به أيضا، هو رسول الله ﷺ", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [67397, 67411]}, {"n": 2, "t": "الذي جاء بالصدق رسول الله ﷺ، والذي صدق به أبو بكر الله ﵁", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 3, "t": "الذي جاء بالصدق: رسول الله ﷺ، والصدق القرآن، والمصدقون به المؤمنون", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [67406, 67410]}, {"n": 4, "t": "الذي جاء بالصدق جبريل، والصدق: القرآن الذي جاء به من عند الله، وصدق به رسول الله ﷺ", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [67407]}, {"n": 5, "t": "الذي جاء بالصدق المؤمنون، والصدق القرآن، وهم المصدقون به", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [67400, 67401, 67402]}]}, "mawaqif": [{"taliq": 5631, "mi": 1, "aya": 33, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 206", "qawl": "", "nass": "أن يقال: إن الله -تعالى ذكره- عنى بقوله: {والذي جاء بالصدق وصدق به} كل من دعا إلى توحيد الله، وتصديق رسوله، والعمل بما ابتعث به رسوله من بين رسول الله وأتباعه والمؤمنين به. وأن يقال: الصدق هو القرآن، وشهادة أن لا إله إلا الله. والمصدق به: المؤمنون بالقرآن، من جميع خلق الله كائنا من كان من نبي الله وأتباعه", "qawaid": ["السياق", "القراءة ورسم المصحف", "ظاهر الآية ولفظها", "ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5631, "mi": 1, "aya": 33, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "5/ 396", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5631, "mi": 1, "aya": 33, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 394", "qawl": "", "nass": "قوله تعالى: {والذي جاء بالصدق} معادل لقوله: {فمن أظلم ممن كذب على الله وكذب بالصدق} ف", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 5631, "mi": 1, "aya": 33, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 396 - 397", "qawl": "العموم", "nass": "لفظ الآية عام مطلق لا يختص بأبي بكر ولا بعلي، بل كل من دخل في عمومها دخل في حكمها. ولا ريب أن أبا بكر وعمر وعثمان وعليا أحق هذه الأمة بالدخول فيها، لكنها لا تختص بهم. وقد قال تعالى: {فمن أظلم ممن كذب على الله وكذب بالصدق إذ جاءه أليس في جهنم مثوى للكافرين والذي جاء بالصدق وصدق به أولئك هم المتقون} الآية، فقد ذم الله? الكاذب على الله والمكذب بالصدق، وهذا ذم عام … والله تعالى مدح الصادق فيما يجيء به والمصدق بهذا الحق. فهذا مدح للنبي، ولكل من آمن به وبما جاء به … ولما كان قوله: {والذي} صنفا من الأصناف لا يقصد به واحد بعينه، أعاد الضمير بصيغة الجمع فقال: {والذي جاء بالصدق وصدق به أولئك هم المتقون}", "qawaid": [], "tabi": ""}, {"taliq": 5631, "mi": 1, "aya": 33, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "12/ 130", "qawl": "الخامس", "nass": "وهذا القول عن مجاهد يشمل كل المؤمنين، فإن المؤمن يقول الحق ويعمل به، والرسول أولى الناس بالدخول في هذه الآية على هذا التفسير، فإنه جاء بالصدق، وصدق المرسلين، وآمن بما أنزل إليه من ربه والمؤمنون، كل آمن بالله وملائكته وكتبه ورسله", "qawaid": [], "tabi": ""}], "mushid": {"i": 8, "imgs": ["039_008_1.png"], "pages": [447], "n": 5, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5631, "masala": "معنى: {والذي جاء بالصدق وصدق به}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الذي جاء بالصدق: رسول الله، والصدق الذي جاء به: لا إله إلا الله، والذي صدق به أيضا: هو رسول الله", "ashab": "", "athar": []}, {"n": 2, "t": "الذي جاء بالصدق: رسول الله، والذي صدق به: أبو بكر", "ashab": "", "athar": []}, {"n": 3, "t": "الذي جاء بالصدق: رسول الله، والصدق: القرآن، والمصدقون به: المؤمنون", "ashab": "", "athar": []}, {"n": 4, "t": "الذي جاء بالصدق: جبريل، والصدق: القرآن الذي جاء به من عند الله، وصدق به: رسول الله", "ashab": "", "athar": []}, {"n": 5, "t": "الذي جاء بالصدق: المؤمنون، والصدق: القرآن، وهم المصدقون به", "ashab": "", "athar": []}, {"n": 6, "t": "الذين جاءوا بالصدق: الأنبياء، والذين صدقوا به: الأتباع", "ashab": "", "athar": []}, {"n": 7, "t": "الذي جاء بالصدق: رسول الله، والذي صدق به: علي", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"], ["ابن تيمية", "رجّح العموم"]], "rules": {"ابن جرير": ["السياق", "القراءة ورسم المصحف", "ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 35, "title": "قوله تعالى: {ليكفر الله عنهم}", "mawsua": {"taliq": 5632, "masala": "قوله تعالى: {ليكفر الله عنهم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن تتعلق بقوله تعالى: {المحسنين}، أي: الذين أحسنوا لكي يكفر", "ashab": "ابن زيد»", "athar": []}, {"n": 2, "t": "أن تتعلق بفعل مضمر مقطوع مما قبله، كأنك قلت: بشرهم الله تعالى بذلك ليكفر. لأن التكفير لا يكون إلا بعد التيسير للخير، و {أسوأ الذي عملوا} هو كفر أهل الجاهلية ومعاصي أهل الإسلام", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5632, "mi": 1, "aya": 35, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 396", "qawl": "", "nass": "أن تتعلق بقوله تعالى: {المحسنين}، أي: الذين أحسنوا لكي يكفر. قاله ابن زيد", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 41, "title": "معنى: {بالحق}", "mawsua": {"taliq": 5634, "masala": "معنى: {بالحق}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: متضمنا الحق في أخباره وأحكامه", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: أنه أنزله بالواجب من إنزاله، وبالاستحقاق لذلك، لما فيه من مصلحة العالم وهداية الناس", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5634, "mi": 1, "aya": 41, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 398", "qawl": "", "nass": "أن يريد: متضمنا الحق في أخباره وأحكامه", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 42, "title": "معنى: {الله يتوفى الأنفس حين موتها والتي لم تمت في منامها} الآية", "mawsua": {"taliq": 5637, "masala": "معنى: {الله يتوفى الأنفس حين موتها والتي لم تمت في منامها} الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن الممسكة: من توفيت وفاة الموت، والمرسلة: من توفيت وفاة النوم", "ashab": "ابن عباس من طريق سعيد بن جبير وما في معناه، وقول سعيد بن جبير، والسدي، وابن زيد", "athar": [67444, 67446]}, {"n": 2, "t": "أن الممسكة والمرسلة في الآية كلاهما توفى وفاة النوم، وأما التي توفيت وفاة الموت فتلك قسم ثالث", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5637, "mi": 1, "aya": 42, "alam": "ابن القيم", "fil": "وجه", "kind": "توجيه", "ref": "2/ 390", "qawl": "الأول", "nass": "والمعنى على هذا القول: أنه يتوفى نفس الميت فيمسكها ولا يرسلها إلى جسدها قبل يوم القيامة، ويتوفى نفس النائم ثم يرسلها إلى جسدها إلى بقية أجلها فيتوفاها الوفاة الأخرى", "qawaid": [], "tabi": ""}, {"taliq": 5637, "mi": 1, "aya": 42, "alam": "ابن تيمية", "fil": "علق", "kind": "تعليق", "ref": "5/ 401", "qawl": "الثاني", "nass": "وعلى هذا يدل الكتاب والسنة؛ فإن الله قال: {الله يتوفي الأنفس حين موتها والتي لم تمت في منامها فيمسك التي قضى عليها الموت ويرسل الأخرى إلى أجل مسمى}، فذكر إمساك التي قضى عليها الموت من هذه الأنفس التي توفاها بالنوم، وأما التي توفاها حين موتها فتلك لم يصفها بإمساك ولا إرسال", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5637, "mi": 1, "aya": 42, "alam": "ابن القيم", "fil": "بين", "kind": "بيان", "ref": "2/ 390 - 391", "qawl": "الأول", "nass": "والذي يترجح هو القول الأول؛ لأنه سبحانه أخبر بوفاتين، وفاة كبرى وهى وفاة الموت، ووفاة صغرى وهى وفاة النوم، وقسم الأرواح قسمين: قسما قضى عليها بالموت فأمسكها عنده وهي التي توفاها وفاة الموت، وقسما لها بقية أجل فردها إلى جسدها إلى استكمال أجلها، وجعل سبحانه الإمساك والإرسال حكمين للوفاتين المذكورتين أولا، فهذه ممسكة وهذه مرسلة، وأخبر أن التي لم تمت هي التي توفاها في منامها، فلو كان قد قسم وفاة النوم إلى قسمين: وفاة موت ووفاة نوم، لم يقل: {والتي لم تمت في منامها} فإنها من حين قبضت ماتت، وهو سبحانه قد أخبر أنها لم تمت فكيف يقول بعد ذلك: {فيمسك التي قضى عليها الموت}. ولمن نصر هذا القول أن يقول قوله تعالى: {فيمسك التي قضى عليها الموت} بعد أن توفاها وفاة النوم، فهو سبحانه توفاها أولا وفاة نوم، ثم قضى عليها الموت بعد ذلك", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5637, "mi": 1, "aya": 42, "alam": "ابن تيمية", "fil": "اختار", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن القيم", "w"]]}, "t": {}, "gen": [["ابن تيمية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {}, "rulesD": {}}}, {"aya": 49, "title": "معنى: {على علم}", "mawsua": {"taliq": 5640, "masala": "معنى: {على علم}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: على علم مني بوجه المكاسب والتجارات وغير ذلك", "ashab": "قتادة»", "athar": []}, {"n": 2, "t": "أن يريد: على علم من الله تعالى في، وشيء سبق لي، واستحقاق حزته عند الله تعالى، لا يضرني معه شيء", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5640, "mi": 1, "aya": 49, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 402", "qawl": "", "nass": "أن يريد: على علم مني بوجه المكاسب والتجارات وغير ذلك. قاله قتادة", "qawaid": [], "tabi": ""}, {"taliq": 5640, "mi": 1, "aya": 49, "alam": "ابن القيم", "fil": "نقل", "kind": "نقل", "ref": "2/ 394", "qawl": "", "nass": "على علم من الله أني له أهل", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 49, "title": "معنى: {على علم}", "mawsua": {"taliq": 5640, "masala": "معنى: {على علم}", "sigha": "زاد قولين", "nasib": "ابن القيم", "aqwal": [{"n": 1, "t": "على علم من الله أني له أهل", "ashab": "", "athar": []}, {"n": 2, "t": "أن المعنى: «قد علمت أني لما أوتيت هذا في الدنيا فلي عند الله منزلة وشرف", "ashab": "", "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 53, "title": "في الذين عنوا بهذه الآية", "tabari": {"page": "20/224", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: عنى الله تعالى ذكره بذلك جميع من أسرف على نفسه من أهل الإيمان والشرك؛ لأن الله عم بقوله: ﴿ياعبادي الذين أسرفوا على أنفسهم﴾ جميع المسرفين، فلم يخصص به مسرفا دون مسرف.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "عني بها قوم من أهل الشرك، قالوا لما دعوا إلى الإيمان بالله: كيف نؤمن وقد أشركنا وزنينا، وقتلنا النفس التي حرم الله، والله يعد فاعل ذلك النار، فما ينفعنا مع ما قد سلف منا الإيمان؟! فنزلت هذه الآية", "taqdim": 0, "n_athar": 8, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["عطاء بن يسار", "تابعي"], ["زيد بن أسلم", "تابعي"], ["قتادة", "تابعي"], ["السدي", "تابعي"], ["ابن زيد", "تابع التابعين"], ["الشعبي", "تابعي"]], "athar": [67491, 67492, 67493, 67494, 67497, 67500, 67501, 67504, 67506, 67507, 67509, 67511, 67518, 67520, 67529]}, {"n": 2, "t": "بل عني بذلك أهل الإسلام. وقالوا: تأويل الكلام: إن الله يغفر الذنوب جميعا لمن يشاء. قالوا: وهي كذلك في مصحف عبد الله. وقالوا: إنما نزلت هذه الآية في قوم صدهم المشركون عن الهجرة وفتنوهم، فأشفقوا ألا يكون لهم توبة", "taqdim": 0, "n_athar": 6, "qailun": [["ابن عمر", "صحابي"], ["ابن سيرين", "تابعي"], ["أبي الكنود", ""], ["القرظي", ""]], "athar": [67489, 67490, 67508, 67524, 67530]}, {"n": 3, "t": "نزل ذلك في قوم كانوا يرون أهل الكبائر من أهل النار، فأعلمهم الله بذلك أنه يغفر الذنوب جميعا لمن يشاء", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عمر", "صحابي"]], "athar": [67489, 67490, 67524]}]}, "mawaqif": [{"taliq": 5641, "mi": 1, "aya": 53, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 230", "qawl": "العموم", "nass": "وأولى الأقوال في ذلك بالصواب قول من قال: عنى -تعالى ذكره- بذلك جميع من أسرف على نفسه من أهل الإيمان والشرك؛ لأن الله عم بقوله: {يا عبادي الذين أسرفوا على أنفسهم} جميع المسرفين، فلم يخصص به مسرفا دون مسرف. فإن قال قائل: فيغفر الله الشرك؟ قيل: نعم، إذا تاب منه المشرك، وإنما عنى بقوله: {إن الله يغفر الذنوب جميعا} لمن يشاء، كما قد ذكرنا قبل أن ابن مسعود كان يقرؤه، وأن الله قد استثنى منه الشرك إذا لم يتب منه صاحبه، فقال: إن الله لا يغفر أن يشرك به، ويغفر ما دون ذلك لمن يشاء، فأخبر أنه لا يغفر الشرك إلا بعد توبة بقوله: {إلا من تاب وآمن وعمل صالحا} [الفرقان: 70]، فأما ما عداه فإن صاحبه في مشيئة ربه؛ إن شاء تفضل عليه، فعفا له عنه، وإن شاء عدل عليه فجازاه به", "qawaid": [], "tabi": ""}, {"taliq": 5641, "mi": 1, "aya": 53, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "7/ 403", "qawl": "", "nass": "هذه الآية عامة في جميع الناس إلى يوم القيامة؛ في كل كافر ومؤمن، أي: إن توبة الكافر تمحو ذنوبه، وتوبة العاصي تمحو ذنبه", "qawaid": [], "tabi": "ابن جرير"}], "mushid": {"i": 9, "imgs": ["039_009_1.png", "039_009_2.png"], "pages": [447, 448], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5641, "masala": "نزول الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها نزلت في قوم من أهل الشرك، قالوا لما دعوا إلى الإيمان بالله: كيف نؤمن وقد أشركنا وزنينا، وقتلنا النفس التي حرم الله، والله يعد فاعل ذلك النار؟! الثاني: نزلت في قوم من أهل الإسلام، وقالوا: تأويل الكلام: إن الله يغفر الذنوب جميعا لمن يشاء، قالوا: وهي كذلك في مصحف عبد الله، وقالوا: إنما نزلت هذه الآية في قوم صدهم المشركون عن الهجرة وفتنوهم، فأشفقوا أن لا يكون لهم توبة. الثالث: نزلت في قوم كانوا يرون أهل الكبائر من أهل النار، فأعلمهم الله بذلك أنه يغفر الذنوب جميعا لمن يشاء", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح العموم"], ["ابن عطية", "رجّح العموم"]], "rules": {}, "rulesD": {}}}, {"aya": 67, "title": "تأويل: ﴿والأرض جميعا قبضته يوم القيامة﴾", "tabari": {"page": "20/249", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿والأرض جميعا قبضته يوم القيامة﴾. يقول تعالى ذكره: والأرض كلها قبضته في يوم القيامة، ﴿والسماوات﴾ كلها ﴿مطويات بيمينه﴾. فالخبر عن الأرض متناه عند قوله: ﴿يوم القيامة﴾، و ﴿والأرض﴾ مرفوعة بقوله: ﴿قبضته﴾، ثم استأنف الخبر عن السماوات فقال: ﴿والسماوات مطويات بيمينه﴾. وهي مرفوعة ب ﴿مطويات﴾.", "taqdim": 1, "n_athar": 11, "qailun": [["ابن عباس", "صحابي"], ["الحسن", "تابعي"], ["عبد الله بن عمر", "صحابي"], ["عبد الله", "صحابي"], ["عبد الله بن مسعود", "صحابي"]], "athar": [67601, 67604, 67607, 67610, 67618, 67619, 67625, 67633, 67634, 67635]}, {"n": 2, "t": "بل السماوات في يمينه، والأرضون في شماله", "taqdim": 0, "n_athar": 6, "qailun": [["عبيد الله بن مقسم", ""], ["عبد الله بن عمر", "صحابي"], ["أبي هريرة", "صحابي"], ["ابن شهاب", "تابع التابعين"], ["أبي أيوب الأنصاري", "صحابي"]], "athar": [67614, 67628]}, {"n": 3, "t": "إن هذه الآية نزلت من أجل يهودي سأل رسول الله ﷺ عن صفة الرب", "taqdim": 0, "n_athar": 2, "qailun": [["سعيد", "تابعي"]], "athar": [67605, 67606]}, {"n": 4, "t": "﴿والأرض جميعا قبضته يوم القيامة والسماوات مطويات بيمينه﴾. يقول: في قدرته؛ نحو قوله: ﴿وما ملكت أيمانكم﴾ [النساء: ٣٦]. أي: وما كانت لكم عليه قدرة. وليس الملك لليمين دون سائر الجسد. قال: وقوله: ﴿قبضته﴾. نحو قولك للرجل: هذا في يدك، وفى قبضتك. والأخبار التي ذكرناها عن رسول الله ﷺ وعن أصحابه وغيرهم، تشهد على بطول هذا القول", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 10, "imgs": ["039_010_1.png"], "pages": [448], "n": 3, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 68, "title": "في الذي عنى الله بالاستثناء في هذه الآية", "tabari": {"page": "20/254", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى به جبريل وميكائيل وإسرافيل وملك الموت", "taqdim": 0, "n_athar": 2, "qailun": [["السدي", "تابعي"], ["أنس بن مالك", "صحابي"]], "athar": [67673, 67685]}, {"n": 2, "t": "عنى بذلك الشهداء", "taqdim": 0, "n_athar": 1, "qailun": [["سعيد بن جبير", "تابعي"]], "athar": [67665]}, {"n": 3, "t": "عنى بالاستثناء في الفزع الشهداء، وفي الصعق جبريل وملك الموت وحملة العرش", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "، والخبر الذي جاء فيه عن رسول الله ﷺ", "taqdim": 0, "n_athar": 1, "qailun": [["أبي هريرة", "صحابي"]], "athar": [67638, 67645, 67655, 67657, 67662, 67676, 67677, 67678]}, {"n": 5, "t": "ثنا يزيد، قال: ثنا سعيد، عن قتادة قوله: ﴿فصعق من في السماوات ومن في الأرض إلا من شاء الله﴾. قال الحسن: يستثنى الله، وما يدع أحدا من أهل السماوات ولا أهل الأرض، إلا أذاقه الموت. قال قتادة: قد استثنى الله، والله أعلم إلى [ما صارت ثنيته] . قال: ذكر لنا أن نبي الله ﷺ قال: \"أتاني ملك فقال: يا محمد، اختر؛ نبيا ملكا، أو نبيا عبدا. فأومأ إلي أن تواضع، قال: نبيا عبدا. قال: فأعطيت خصلتين؛ أن جعلت أول من تنشق عنه الأرض، وأول شا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5652, "mi": 1, "aya": 68, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 257", "qawl": "الثالث", "nass": "لأن الصعقة في هذا الموضع: الموت، والشهداء وإن كانوا عند الله أحياء -كما أخبر الله تعالى ذكره- فإنهم قد ذاقوا الموت قبل ذلك، وإنما عنى -جل ثناؤه- بالاستثناء في هذا الموضع: الاستثناء من الذين صعقوا عند نفخة الصعق، لا من الذين قد ماتوا قبل ذلك بزمان ودهر طويل؛ وذلك أنه لو جاز أن يكون المراد بذلك من قد هلك وذاق الموت قبل وقت نفخة الصعق؛ وجب أن يكون المراد بذلك: من قد هلك، فذاق الموت من قبل ذلك، لأنه ممن لا يصعق في ذلك الوقت إذا كان الميت لا يجدد له موت آخر في تلك الحال", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 11, "imgs": ["039_011_1.png"], "pages": [448], "n": 3, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 5652, "masala": "الذي عنى الله بالاستثناء", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "عنى به: جبريل، وميكائيل، وإسرافيل، وملك الموت", "ashab": "", "athar": []}, {"n": 2, "t": "عنى بذلك: الشهداء", "ashab": "", "athar": []}, {"n": 3, "t": "عنى بالاستثناء في الفزع: الشهداء، وفي الصعق: جبريل، وملك الموت، وحملة العرش", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن جرير", "r"]]}, "t": {"3": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 69, "title": "تأويل: ﴿وجيء بالنبيين والشهداء﴾", "tabari": {"page": "20/262", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وجيء بالنبيين والشهداء﴾. يقول : وجيء بالنبيين ليسألهم ربهم عما أجابتهم به أممهم، وردت عليهم في الدنيا، حين أتتهم رسالة الله، ﴿والشهداء﴾. يعنى بالشهداء أمة محمد ﷺ، يستشهدهم ربهم على الرسل، فيما ذكرت من تبليغها رسالة الله التي أرسلهم بها ربهم إلى أممها، إذا جحدت أممهم أن يكونوا أبلغوهم رسالة الله.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "عنى بقوله: ﴿والشهداء﴾: الذين قتلوا في سبيل الله. وليس لما قالوا من ذلك في هذا الموضع كبير معنى؛ لأن عقيب قوله: ﴿وجيء بالنبيين والشهداء﴾؛ ﴿وقضي بينهم بالحق﴾. وفى ذلك دليل واضح على صحة ما قلنا، من أنه إنما دعى بالنبيين والشهداء، للقضاء بين الأنبياء وأممها، وأن الشهداء إنما هي جمع شهيد، الذين يشهدون للأنبياء على أممهم، كما ذكرنا", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [67699, 67700]}, {"n": 3, "t": "ما حكينا قوله من القول الآخر", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [67692, 67694, 67697, 67702]}]}, "mawaqif": [{"taliq": 5655, "mi": 1, "aya": 69, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 262 - 263", "qawl": "الأول", "nass": "والشهداء: جمع شهيد، وهذا نظير قول الله: {وكذلك جعلناكم أمة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا} [البقرة: 143]", "qawaid": ["القرآن والنظائر", "السياق", "أقوال السلف", "ظاهر الآية ولفظها"], "tabi": ""}, {"taliq": 5655, "mi": 1, "aya": 69, "alam": "ابن عطية", "fil": "وبنحوه", "kind": "موافقة", "ref": "7/ 413 بتصرف", "qawl": "", "nass": "وهذا أيضا يزول عنه معنى التوعد، وهو مقصد الآية", "qawaid": ["ظاهر الآية ولفظها"], "tabi": "ابن جرير"}, {"taliq": 5655, "mi": 1, "aya": 69, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "", "qawl": "", "nass": "ويحتمل أن يريد بقوله: {والشهداء}: الأنبياء أنفسهم، فيكون من عطف الصفة على الصفة بالواو، كما تقول: جاء زيد الكريم والعاقل", "qawaid": [], "tabi": ""}], "mawsua": {"taliq": 5655, "masala": "معنى الشهداء", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "أنهم الذين يشهدون للأنبياء بالبلاغ", "ashab": "", "athar": []}, {"n": 2, "t": "أنهم الذين استشهدوا في سبيل الله", "ashab": "", "athar": []}, {"n": 3, "t": "أنهم الحفظة", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["القرآن والنظائر", "السياق", "أقوال السلف", "ظاهر الآية ولفظها"], "ابن عطية": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 73, "title": "في موضع جواب \"إذا\" التي في قوله: ﴿حتى إذا جاءوها﴾", "tabari": {"page": "20/268", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك عندى بالصواب قول من قال: الجواب متروك. وإن كان القول الآخر غير مدفوع، وذلك أن قوله: ﴿وقال لهم خزنتها سلام عليكم طبتم فادخلوها خالدين﴾. يدل على أن في الكلام متروكا، إذ كان عقيبه ﴿وقالوا الحمد لله الذي صدقنا وعده﴾. وإذا كان ذلك كذلك، فمعنى الكلام: حتى إذا جاءوها، وفتحت أبوابها، وقال لهم خزنتها: سلام عليكم طبتم، فادخلوها خالدين. دخلوها وقالوا: الحمد لله الذي صدقنا وعده. وعنى بقوله: ﴿سلام عليكم﴾: أمنة من الله لكم، أن ينالكم بعد مكروه أو أذى وقوله: ﴿طبتم﴾. يقول: طابت أعمالكم في الدنيا، فطاب اليوم مثواكم.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "يقال: إن قوله: ﴿وقال لهم خزنتها﴾. في معنى: قال لهم، كأنه يلغى الواو، وقد جاء في الشعر شيء يشبه أن تكون الواو زائدة، كما قال الشاعر :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "أدخلت في \"حتى إذا\" وفى \"فلما\" الواو، في جوابها، وأخرجت، فأما من أخرجها فلا شيء فيه، ومن أدخلها شبه الأوائل بالتعجب، فجعل الثاني نسقا على الأول، وإن كان الثاني جوابا، كأنه قال: أتعجب لهذا وهذا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [{"i": 4, "aya": 8, "imgs": ["039_004_1.png"], "pages": [446], "ihala": 0}], "others": {"7": [{"id": 5606, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 375) احتمالًا آخر، فقال: «ويُحتمل أن تكون مخاطبة لجميع الناس؛ لأن الله غنيٌّ عن جميع الناس، وهم فقراء إليه».", "mawaqif": [{"taliq": 5606, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 375", "qawl": "", "nass": "ويحتمل أن تكون مخاطبة لجميع الناس؛ لأن الله غني عن جميع الناس، وهم فقراء إليه", "qawaid": [], "tabi": ""}]}], "8": [{"id": 5608, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 376) في قوله تعالى: {ثُمَّ إذا خَوَّلَهُ نِعْمَةً مِنهُ} احتمالين، فقال: «يُحتمل أن يريد: في كشف الضر المذكور، أو يريد: أيَّ نعمة بانت». وعلَّق عليهما بقوله: «واللفظ يعُمُّهما».", "mawaqif": [{"taliq": 5608, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 376", "qawl": "", "nass": "يحتمل أن يريد: في كشف الضر المذكور، أو يريد: أي نعمة بانت", "qawaid": [], "tabi": ""}]}, {"id": 5609, "kinds": "خلاف،نقد،توجيه،نقل", "text": "نقل ابن جرير (20/ 172)، وابن عطية (7/ 377) في «ما» من قوله تعالى: {نَسِيَ ما كانَ يَدْعُو إلَيْهِ مِن قَبْلُ} قولين: الأول: أن {ما} مصدرية.\nووجَّهه ابنُ عطية بقوله: «والمعنى: نسيَ دعاءَه إليه في حال الضرر، ورجع إلى كفره».\nووجَّهه ابنُ تيمية (5/ 384) بأن «تقديره: نسي كونه يدعو الله إلى حاجته، كما قال تعالى في الآية الأخرى: {فَلَمّا كَشَفْنا عَنْهُ ضُرَّهُ مَرَّ كَأَنْ لَمْ يَدْعُنا إلى ضُرٍّ مَسَّهُ} [يونس: 12]».\nثم استدرك عليه قائلًا: «لكن على هذا يبقى الضمير في {إليه} عائدًا على غير مذكور، بخلاف ما إذا جُعلت بمعنى: الذي، فإن التقدير: نسي حاجته الذي دعاني إليها من قبل، فنسي دعاءه الله الذي كان سبب الحاجة».الثاني: أن {ما} بمعنى: الذي، والمراد بها الله.\nووجَّهه ابنُ عطية بقوله: «وهذا كنحو قوله: {ولا أنْتُمْ عابِدُونَ ما أعْبُدُ} [الكافرون: 3]، وقد تقع ما» مكان «من» فيما لا يُحصى كثرةً من كلامهم\".\nثم زاد ابنُ عطية احتمالين آخرين: أحدهما: «أن تكون {ما} نافية، ويكون قوله: {نَسِيَ} كلامًا تامًّا، ثم نفى أن يكون دعاء هذا الكافر خالصًا لله ومقصودًا به من قبل النعمة، أي: في حال الضُّر». والآخر: «أن تكون {ما} نافية، ويكون قوله: {مِن قَبْلُ} يريد: من قَبْل الضرر». ثم وجَّهه بقوله: «فكأنه يقول: ولم يكن هذا الكافر يدعو في سائر زمنه قبل الضرر، بل ألجأه ضررُه إلى الدعاء».", "mawaqif": [{"taliq": 5609, "mi": 0, "aya": 8, "alam": "ابن جرير", "fil": "نقل", "kind": "نقل", "ref": "20/ 172", "qawl": "", "nass": "ما", "qawaid": [], "tabi": ""}, {"taliq": 5609, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 377", "qawl": "", "nass": "ما", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5609, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "وجهه", "kind": "توجيه", "ref": "", "qawl": "", "nass": "والمعنى: نسي دعاءه إليه في حال الضرر، ورجع إلى كفره", "qawaid": [], "tabi": ""}, {"taliq": 5609, "mi": 0, "aya": 8, "alam": "ابن تيمية", "fil": "وجهه", "kind": "توجيه", "ref": "5/ 384", "qawl": "", "nass": "تقديره: نسي كونه يدعو الله إلى حاجته، كما قال تعالى في الآية الأخرى: {فلما كشفنا عنه ضره مر كأن لم يدعنا إلى ضر مسه} [يونس: 12]", "qawaid": [], "tabi": ""}, {"taliq": 5609, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "وجهه", "kind": "توجيه", "ref": "", "qawl": "", "nass": "وهذا كنحو قوله: {ولا أنتم عابدون ما أعبد} [الكافرون: 3]، وقد تقع ما", "qawaid": [], "tabi": ""}, {"taliq": 5609, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "", "qawl": "", "nass": "أن تكون {ما} نافية، ويكون قوله: {نسي} كلاما تاما، ثم نفى أن يكون دعاء هذا الكافر خالصا لله ومقصودا به من قبل النعمة، أي: في حال الضر", "qawaid": [], "tabi": ""}]}], "9": [{"id": 5612, "kinds": "توجيه،نقل", "text": "وجَّه ابنُ كثير (12/ 116) قول ابن عمر بقوله: «وإنما قال ابن عمر ذلك؛ لكثرة صلاة أمير المؤمنين عثمان بالليل وقراءته، حتى إنه ربما قرأ القرآن في ركعة، كما روى ذلك أبو عبيدة عنه».", "mawaqif": [{"taliq": 5612, "mi": 0, "aya": 9, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "12/ 116", "qawl": "ابن عمر", "nass": "وإنما قال ابن عمر ذلك؛ لكثرة صلاة أمير المؤمنين عثمان بالليل وقراءته، حتى إنه ربما قرأ القرآن في ركعة، كما روى ذلك أبو عبيدة عنه", "qawaid": [], "tabi": ""}]}], "10": [{"id": 5614, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (7/ 381) عن قوم: أن المراد بالأرض هنا: الجنة. ثم انتقده مستندًا إلى عدم الدليل قائلًا: «وفي هذا القول تحكُّم لا دليل عليه».", "mawaqif": [{"taliq": 5614, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 381", "qawl": "", "nass": "وفي هذا القول تحكم لا دليل عليه", "qawaid": ["عدم الدليل على غيره"], "tabi": ""}]}, {"id": 5615, "kinds": "توجيه،تعليق،نقل", "text": "أفادت الآثارُ أنّ معنى قوله تعالى: {بِغَيْرِ حِسابٍ}: «أن أجور الصابرين توفّى بغير حصر ولا عدٍّ، بل جزافًا».\nثم علَّق عليه ابنُ عطية (7/ 381 - 382) بقوله: «وهذه استعارة للكثرة التي لا تُحصى … وإلى هذا التأويل ذهب جمهور المفسرين، حتى قال قتادة: ما ثَمَّ -واللهِ- مكيال ولا ميزان، وفي بعض الحديث أنه لما نزلت: {واللَّهُ يُضاعِفُ لِمَن يَشاءُ} [البقرة: 261] قال عليه الصلاة والسلام: «اللهم، زِدْ أُمَّتي». فنزلت: {فَيُضاعِفَهُ لَهُ أضْعافًا كَثِيرَةً} [البقرة: 245]، فقال: «اللهم، زِدْ أُمَّتي». فنزلت هذه الآية، فقال: «رضيتُ، يا رب»». ثم ذكر (7/ 381) احتمالًا آخر في معنى الآية: «أن الصابر يوفّى أجره، ثم لا يحاسب عن النعيم، ولا يُتابَع بذنوب». ثم وجَّهه بقوله: «فيقع {الصّابِرُونَ} في هذه الآية على الجماعة التي ذكرها النبي عليه الصلاة والسلام أنها تدخل الجنة بغير حساب، وفي قوله: «يدخل الجنة من أمتي سبعون ألفًا بغير حساب، الذين لا يتطيَّرون ولا يَكْتَوُون ولا يَسْتَرْقُون، وعلى ربهم يتوكلون، وجوههم على صورة القمر ليلة البدر … » الحديثَ على اختلاف ترتيباته».", "mawaqif": []}], "15": [{"id": 5616, "kinds": "تعليق", "text": "علَّق ابنُ عطية (7/ 382) على قول ابن عباس وما في معناه بقوله: «فهذا كما لو قال: خسروا أنفسهم ونعيمهم، أي: الذي كان يكون لهم».", "mawaqif": [{"taliq": 5616, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 382", "qawl": "ابن عباس", "nass": "فهذا كما لو قال: خسروا أنفسهم ونعيمهم، أي: الذي كان يكون لهم", "qawaid": [], "tabi": ""}]}], "17": [{"id": 5617, "kinds": "ترجيح،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 383) قول زيد، ونقل عن ابن إسحاق: أن «الإشارة بها إلى عبد الرحمن بن عوف، وسعد بن أبي وقاص، وسعيد بن زيد، والزبير، وذلك أنه لما أسلم أبو بكر سمعوا ذلك، فجاؤوه، فقالوا: أسلمتَ؟ قال: نعم. وذكَّرهم بالله تعالى، فآمنوا بأجمعهم، فنزلت فيهم هذه الآية». ثم علَّق بقوله: «وهي على كل حالٍ عامَّة في الناس إلى يوم القيامة، يتناولهم حكمها».\nوذكر ابنُ كثير (12/ 118 - 119) قول زيد، ثم رجَّح العموم قائلًا: «والصحيح أنها شاملةٌ لهم ولغيرهم، ممن اجتنب عبادة الأوثان، وأناب إلى عبادة الرحمن، فهؤلاء هم الذين لهم البشرى في الحياة الدنيا وفي الآخرة».", "mawaqif": [{"taliq": 5617, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 383", "qawl": "زيد", "nass": "الإشارة بها إلى عبد الرحمن بن عوف، وسعد بن أبي وقاص، وسعيد بن زيد، والزبير، وذلك أنه لما أسلم أبو بكر سمعوا ذلك، فجاؤوه، فقالوا: أسلمت؟ قال: نعم. وذكرهم بالله تعالى، فآمنوا بأجمعهم، فنزلت فيهم هذه الآية", "qawaid": [], "tabi": ""}, {"taliq": 5617, "mi": 0, "aya": 17, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 118 - 119", "qawl": "زيد", "nass": "والصحيح أنها شاملة لهم ولغيرهم، ممن اجتنب عبادة الأوثان، وأناب إلى عبادة الرحمن، فهؤلاء هم الذين لهم البشرى في الحياة الدنيا وفي الآخرة", "qawaid": [], "tabi": ""}]}], "18": [{"id": 5618, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (20/ 184 - 185) في معنى: {فَيَتَّبِعُونَ أحْسَنَهُ} سوى قول قتادة، والسُّدِّيّ.", "mawaqif": []}], "21": [{"id": 5620, "kinds": "خلاف،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 385) في تفسير الآية معنى قول الشعبي: «أن كل ماءٍ عذب في الأرض فمن السماء نزل». ومعنى قول الحسن بن يَنّاق: «أن الإشارة إلى العيون، وليست العيون من المطر، ولكن ماؤها نازل من السماء». ثم علَّق عليهما بقوله: «والقولان متقاربان».", "mawaqif": [{"taliq": 5620, "mi": 0, "aya": 21, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 385", "qawl": "الشعبي", "nass": "أن كل ماء عذب في الأرض فمن السماء نزل", "qawaid": [], "tabi": ""}]}], "22": [{"id": 5621, "kinds": "بيان،نقل", "text": "قال ابنُ عطية (7/ 387): «روي أن هذه الآية: {أفَمَن شَرَحَ اللَّهُ صَدْرَهُ لِلْإسْلامِ} الآية، نزلت في عليٍّ وحمزة، وأبي لهب وابنه، وهما اللذان كانا من القاسية قلوبهم».", "mawaqif": [{"taliq": 5621, "mi": 0, "aya": 22, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 387", "qawl": "", "nass": "روي أن هذه الآية: {أفمن شرح الله صدره للإسلام} الآية، نزلت في علي وحمزة، وأبي لهب وابنه، وهما اللذان كانا من القاسية قلوبهم", "qawaid": [], "tabi": ""}]}], "23": [{"id": 5622, "kinds": "توجيه،بيان،نقل", "text": "أفاد قولُ مقاتل عود اسم الإشارة في قوله تعالى: {ذَلِكَ هُدى اللهِ} إلى القرآن.\nووجَّهه ابنُ عطية (7/ 389) بقوله: «أي: ذلك الذي هذه صفته هدى الله»، وزاد ابنُ عطية في المشار إليه بـ {ذلك} قولًا آخر: «أن يشير إلى الخشية واقشعرار الجلد». ثم وجَّهه بقوله: «أي: ذلك أمارة هدى الله».", "mawaqif": [{"taliq": 5622, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "وجهه", "kind": "توجيه", "ref": "7/ 389", "qawl": "", "nass": "أي: ذلك الذي هذه صفته هدى الله", "qawaid": [], "tabi": ""}, {"taliq": 5622, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "", "qawl": "", "nass": "أن يشير إلى الخشية واقشعرار الجلد", "qawaid": [], "tabi": ""}]}], "24": [{"id": 5624, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 389) في معنى: {يَتَّقِي بِوَجْهِهِ} قول ابن عباس، وقول مجاهد، ونقل قولًا عن فرقة أن «المعنى: صفة ما ينالهم من كثرة العذاب، وذلك أن يتقيه بجميع جوارحه وفيه حواسه، فإذا بلغ به العذاب إلى هذه الغاية ظهر أنه لا متجاوز بعدها». ثم علَّق عليه بقوله: «وهذا المعنى عندي أقْيَس بلاغة … ».", "mawaqif": [{"taliq": 5624, "mi": 0, "aya": 24, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 389", "qawl": "ابن عباس", "nass": "المعنى: صفة ما ينالهم من كثرة العذاب، وذلك أن يتقيه بجميع جوارحه وفيه حواسه، فإذا بلغ به العذاب إلى هذه الغاية ظهر أنه لا متجاوز بعدها", "qawaid": [], "tabi": ""}]}], "28": [{"id": 5625, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (20/ 196) في معنى: {قُرْآنًا عَرَبِيًّا غَيْرَ ذِي عِوَجٍ} سوى قول مجاهد.", "mawaqif": []}, {"id": 5626, "kinds": "نقل", "text": "نقل ابنُ عطية (7/ 390) في معنى: {غَيْرَ ذِي عِوَجٍ} عن عثمان بن عفان رضي الله عنهما قوله: غير متضاد.", "mawaqif": [{"taliq": 5626, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 390", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "29": [{"id": 5627, "kinds": "ترجيح،نقل", "text": "ذكر ابن جرير (20/ 197) قراءتين في الآية: الأولى: «رَجُلًا سالِمًا» بالألف. الثانية: {رجلًا سَلَمًا} بغير ألف.\nورجَّح ابنُ جرير «أنهما قراءتان معروفتان، قد قرأ بكل واحدةٍ منهما علماء من القرأة، متقاربتا المعنى، فبأيَّتِهِما قرأ القارئ فمصيبٌ».", "mawaqif": [{"taliq": 5627, "mi": 0, "aya": 29, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 197", "qawl": "", "nass": "رجلا سالما", "qawaid": [], "tabi": ""}, {"taliq": 5627, "mi": 0, "aya": 29, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "أنهما قراءتان معروفتان، قد قرأ بكل واحدة منهما علماء من القرأة، متقاربتا المعنى، فبأيتهما قرأ القارئ فمصيب", "qawaid": [], "tabi": ""}]}], "32": [{"id": 5629, "kinds": "غيره", "text": "لم يذكر ابن جرير (20/ 203) في معنى: {وكَذَّبَ بِالصِّدْقِ إذْ جاءَهُ} سوى قول قتادة.", "mawaqif": []}], "33": [{"id": 5630, "kinds": "نقد،نقل", "text": "نقل ابنُ تيمية في منهاج السنة النبوية (7/ 188 - 189) هذا القول عن مجاهد، ثم انتقده مستندًا إلى ضعف إسناده، وظاهر الآية بأنّ هذا النقل غير ثابت عنه، والثابت عنه خلافه، وبأن «هذا مُعارَض بما هو أشهر منه عند أهل التفسير، وهو أن الذي جاء بالصِّدق: محمد، والذي صدَّق به: أبو بكر. فإن هذا يقوله طائفة، وذكره الطبري بإسناده إلى علي». وبأن «لفظ الآية عام مطلق، لا يختص بأبي بكر ولا بعلي».", "mawaqif": [{"taliq": 5630, "mi": 0, "aya": 33, "alam": "ابن تيمية", "fil": "نقل", "kind": "نقل", "ref": "", "qawl": "عن مجاهد", "nass": "هذا معارض بما هو أشهر منه عند أهل التفسير، وهو أن الذي جاء بالصدق: محمد، والذي صدق به: أبو بكر. فإن هذا يقوله طائفة، وذكره الطبري بإسناده إلى علي", "qawaid": ["نقد الرواية (السند، الإسرائيليات)", "ظاهر الآية ولفظها"], "tabi": ""}]}], "41": [{"id": 5633, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (20/ 214) في معنى: {وما أنْتَ عَلَيْهِمْ بِوَكِيلٍ} سوى قول قتادة، والسُّدّيّ.", "mawaqif": []}], "42": [{"id": 5635, "kinds": "ترجيح،نقد،بيان،نقل", "text": "أفاد أثرُ ابنِ عباس التفرقة بين النفس والروح، وقد انتقده ابنُ عطية (7/ 398) قائلًا: «وكثَّرت فرقة في هذه الآية وهذا المعنى، ففرَّقت بين النَّفْس والروح، وفرَّق قومٌ أيضًا بين نفس التمييز ونفس التَّخَيُّل، إلى غير ذلك من الأقوال التي هي غلبة ظن … فظاهرٌ أن التفصيل والخوض في هذا كله عناء، وإن كان قد تعرَّض للقول في هذا ونحوه الأئمة، ذكر الثعلبي وغيره، عن ابن عباس أنه قال: … » وذكر معنى قول ابن عباس.\nثم رجَّح -مستندًا إلى القرآن، والسنة- عدم التفريق بينهما قائلًا: «وحقيقة الأمر في هذا هي مما استأثر الله تبارك وتعالى به، وغيَّبَه عن عباده في قوله سبحانه: {قُلِ الرُّوحُ مِن أمْرِ رَبِّي} [الإسراء: 85]، ويكفيك أن في هذه الآية: {يَتَوَفّى الأَنْفُسَ}، وفي الحديث الصحيح: أن الله قَبَضَ أرواحنا حين شاء، وردَّها علينا حين شاء. في حديث بلال في الوادي، فقد نطقت الشريعة بقبض الرُّوح والنفس في النوم، وقد قال الله تعالى: {قُلِ الرُّوحُ مِن أمْرِ رَبِّي} [الإسراء: 85]».", "mawaqif": [{"taliq": 5635, "mi": 0, "aya": 42, "alam": "ابن عطية", "fil": "انتقده", "kind": "نقد", "ref": "7/ 398", "qawl": "", "nass": "وكثرت فرقة في هذه الآية وهذا المعنى، ففرقت بين النفس والروح، وفرق قوم أيضا بين نفس التمييز ونفس التخيل، إلى غير ذلك من الأقوال التي هي غلبة ظن … فظاهر أن التفصيل والخوض في هذا كله عناء، وإن كان قد تعرض للقول في هذا ونحوه الأئمة، ذكر الثعلبي وغيره، عن ابن عباس أنه قال: …", "qawaid": ["القرآن والنظائر", "السنة"], "tabi": ""}]}, {"id": 5636, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (20/ 215 - 216) في معنى: {اللَّهُ يَتَوَفّى الأَنْفُسَ حِينَ مَوْتِها والَّتِي لَمْ تَمُتْ فِي مَنامِها} الآية، سوى قول سعيد بن جبير من طريق جعفر، وقول السُّدّي، وابن زيد.", "mawaqif": []}], "43": [{"id": 5638, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (20/ 217) في معنى: {أمِ اتَّخَذُوا مِن دُونِ اللَّهِ شُفَعاءَ} سوى قول قتادة.", "mawaqif": []}], "45": [{"id": 5639, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (12/ 134) في معنى: {اشمأزت} قول مجاهد، وقتادة، والسُّدّي، ونقل عن ابن زيد قوله: استكبرت. ثم علَّق عليه بقوله: «كما قال تعالى: {إنَّهُمْ كانُوا إذا قِيلَ لَهُمْ لا إلَهَ إلا اللَّهُ يَسْتَكْبِرُونَ} [الصافات: 35]، أي: عن المتابعة والانقياد لها، فقلوبهم لا تقبل الخير، ومن لم يقبل الخير يقبل الشر».", "mawaqif": [{"taliq": 5639, "mi": 0, "aya": 45, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 134", "qawl": "مجاهد", "nass": "كما قال تعالى: {إنهم كانوا إذا قيل لهم لا إله إلا الله يستكبرون} [الصافات: 35]، أي: عن المتابعة والانقياد لها، فقلوبهم لا تقبل الخير، ومن لم يقبل الخير يقبل الشر", "qawaid": [], "tabi": ""}]}], "55": [{"id": 5642, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 232) غيرَ قول السُّدّيّ.", "mawaqif": []}], "56": [{"id": 5643, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 234 - 235) غير قول السُّدّيّ، وقول مجاهد.", "mawaqif": []}, {"id": 5644, "kinds": "حصر", "text": "لم يذكر ابن جرير (20/ 235) غير قول السُّدّيّ، وقتادة.", "mawaqif": []}], "59": [{"id": 5645, "kinds": "ترجيح،توجيه،نقل", "text": "ذكر ابنُ جرير (20/ 238) هذه القراءة، ووجّهها بقوله: «وقد رُوي عن رسول الله صلى الله عليه وسلم أنه قرأ ذلك بكسر جميعه على وجه الخطاب للنفس، كأنه قال: أن تقول نفس: يا حسرتا على ما فرطتِ في جنب الله، بلى قد جاءتكِ أيتها النفس آياتي، فكذبتِ بها. أجرى الكلام كله على النفس؛ إذ كان ابتداء الكلام بها جرى».\nوبنحوه قال ابنُ عطية (7/ 407).\nثم رجّح ابنُ جرير -مستندًا لإجماع الحجة من القراء- قراءة الفتح: «والقراءة التي لا أستجيز خلافها ما جاءت به قراءُ الأمصار مجمعة عليه، نقلًا عن رسول الله صلى الله عليه وسلم، وهو الفتح في جميع ذلك».", "mawaqif": [{"taliq": 5645, "mi": 0, "aya": 59, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 238", "qawl": "", "nass": "وقد روي عن رسول الله صلى الله عليه وسلم أنه قرأ ذلك بكسر جميعه على وجه الخطاب للنفس، كأنه قال: أن تقول نفس: يا حسرتا على ما فرطت في جنب الله، بلى قد جاءتك أيتها النفس آياتي، فكذبت بها. أجرى الكلام كله على النفس؛ إذ كان ابتداء الكلام بها جرى", "qawaid": [], "tabi": ""}, {"taliq": 5645, "mi": 0, "aya": 59, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 407", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5645, "mi": 0, "aya": 59, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "", "nass": "والقراءة التي لا أستجيز خلافها ما جاءت به قراء الأمصار مجمعة عليه، نقلا عن رسول الله صلى الله عليه وسلم، وهو الفتح في جميع ذلك", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}]}], "60": [{"id": 5646, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 408) أن ظاهر قوله: {وجوههم مسودة} يعني: «أن لون وجوههم يتغير ويسوَّد حقيقة». ثم ذكر احتمالًا آخر، فقال: «ويحتمل أن يكون في العبارة تجوّز، وعبّر بالسواد عن اربداد وجوههم، وغالب همِّهم، وظاهر كآبتهم».", "mawaqif": [{"taliq": 5646, "mi": 0, "aya": 60, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 408", "qawl": "", "nass": "أن لون وجوههم يتغير ويسود حقيقة", "qawaid": [], "tabi": ""}]}], "61": [{"id": 5647, "kinds": "تعليق،نقل", "text": "ذكر ابنُ جرير (20/ 241) هذه القراءة، وقراءة من قرأ ذلك على الإفراد، ثم علّق قائلًا: «والصواب عندي من القول في ذلك أنهما قراءتان مستفيضتان، قد قرأ بكل واحدة منهما علماء من القراء، فبأيتهما قرأ القارئ فمصيب؛ لاتفاق معنييهما؛ والعرب توحد مثل ذلك أحيانًا وتجمع بمعنى واحد».\nوعلّق ابنُ عطية (7/ 408) على قراءة الجمع، فقال: «وقرأ حمزة، والكسائي، وأبو بكر عن عاصم: «بِمَفازاتِهِمْ» على الجمع مِن حيث النجاة أنواع؛ الأسباب مختلفة، وهي قراءة الحسن، والأعرج، وأبي عبد الرحمن، والأعمش، وفي الكلام حذف مضاف، تقديره: وينجي الله الذين اتقوا بأسباب أو بدواعي مفازاتهم».", "mawaqif": [{"taliq": 5647, "mi": 0, "aya": 61, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 241", "qawl": "", "nass": "والصواب عندي من القول في ذلك أنهما قراءتان مستفيضتان، قد قرأ بكل واحدة منهما علماء من القراء، فبأيتهما قرأ القارئ فمصيب؛ لاتفاق معنييهما؛ والعرب توحد مثل ذلك أحيانا وتجمع بمعنى واحد", "qawaid": [], "tabi": ""}, {"taliq": 5647, "mi": 0, "aya": 61, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 408", "qawl": "", "nass": "وقرأ حمزة، والكسائي، وأبو بكر عن عاصم: «بمفازاتهم", "qawaid": [], "tabi": ""}]}], "63": [{"id": 5648, "kinds": "نقد،توجيه،نقل", "text": "انتقد ابنُ عطية (8/ 408 - 409) قول السُّدّي، فقال: «وقال السُّدّي: المقاليد: الخزائن. وهذه عبارة غير جيدة». ثم وجّهه بقوله: «ويشبه أن يقول قائل: المقاليد: إشارة إلى الخزائن، أو دالة عليها. فيسوغ هذا القول».", "mawaqif": [{"taliq": 5648, "mi": 0, "aya": 63, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "8/ 408 - 409", "qawl": "السدي", "nass": "وقال السدي: المقاليد: الخزائن. وهذه عبارة غير جيدة", "qawaid": [], "tabi": ""}]}, {"id": 5649, "kinds": "تعليق", "text": "لم يذكر ابنُ جرير (20/ 241 - 242) في معنى: {له مقاليد} غير قول ابن زيد، والسُّدّي، ومجاهد، وابن عباس من طريق علي.\nوعلّق ابنُ عطية (7/ 408) على تفسير المقاليد بالمفاتيح بقوله: «وهذه استعارة، كما تقول: بيدك -يا فلان- مفتاح هذا الأمر، إذا كان قديرًا على السعي فيه».", "mawaqif": [{"taliq": 5649, "mi": 0, "aya": 63, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 408", "qawl": "", "nass": "وهذه استعارة، كما تقول: بيدك -يا فلان- مفتاح هذا الأمر، إذا كان قديرا على السعي فيه", "qawaid": [], "tabi": ""}]}], "67": [{"id": 5650, "kinds": "نقد،توجيه،بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 411) هذا الأثر، ثم علّق عليه قائلًا: «فرسول الله صلى الله عليه وسلم تمثّل بالآية، وقد كانت نزلت. وقوله في الحديث: «تصديقًا له». أي: في أنه لم يقل إلا ما رأى في كتب اليهود، ولكن النبي صلى الله عليه وسلم أنكر المعنى؛ لأن التجسيم فيه ظاهر، واليهود معروفون باعتقاده، ولا يحسنون حمله على تأويله من أن الأصبع عبارة عن القدرة، أو من أنها أصبع خلق يخلق لذلك، ويعضّدها تنكير الأصبع».\nوما قاله ابن عطيه باطل، والحق إثبات صفه الأصابع لله تعالى على ما يليق بكماله وعظمته وجلاله، وهو إجماع السلف من الصحابة والتابعين وأتباعهم. ينظر: الشريعة 3/ 1147 - 1177، والإبانة 3/ 91 - 131، وشرح أصول اعتقاد أهل السنة والجماعة 2/ 451 - 480.", "mawaqif": [{"taliq": 5650, "mi": 0, "aya": 67, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 411", "qawl": "", "nass": "فرسول الله صلى الله عليه وسلم تمثل بالآية، وقد كانت نزلت. وقوله في الحديث: «تصديقا له", "qawaid": [], "tabi": ""}]}, {"id": 5651, "kinds": "خلاف،بيان،نقل", "text": "بيّن ابنُ جرير (20/ 245 - 251) أن الخبر عن الأرض في قوله: {والأرض جميعا قبضته} مُتَناهٍ عند قوله تعالى: {يوم القيامة}، ثم استُأنف الخبر عن السماوات بقوله: {والسماوات مطويات بيمينه}، ثم حكى خلافًا عن السلف في ذلك على قولين، الأول: «أن السماوات والأرض جميعًا بيمينه». الثاني: «أن السماوات بيمينه، والأرضون بشماله».", "mawaqif": [{"taliq": 5651, "mi": 0, "aya": 67, "alam": "ابن جرير", "fil": "بين", "kind": "بيان", "ref": "20/ 245 - 251", "qawl": "", "nass": "أن السماوات والأرض جميعا بيمينه", "qawaid": [], "tabi": ""}]}], "69": [{"id": 5653, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 262) غير قول السُّدّي، وقتادة، وكذا في تفسير الجزء التالي من الآية.", "mawaqif": []}, {"id": 5654, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (7/ 413) إضافةً إلى ما ورد في أقوال السلف قولًا آخر في قوله: {ووضع الكتاب} [الكهف: 49] فقال: «وقالت فرقة: وضع اللوح المحفوظ». ثم انتقده -مستندًا إلى ظاهر الآية- بقوله: «وهذا شاذ، وليس فيه معنى التوعد، وهو مقصد الآية».", "mawaqif": [{"taliq": 5654, "mi": 0, "aya": 69, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 413", "qawl": "", "nass": "وقالت فرقة: وضع اللوح المحفوظ", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "71": [{"id": 5656, "kinds": "نقل", "text": "ذكر ابنُ جرير (20/ 264) في قوله: {وينذرونكم لقاء يومكم هذا} احتمالين، فقال: «{وينذرونكم لقاء يومكم هذا} يقول: وينذرونكم ما تلقون في يومكم هذا. وقد يحتمل أن يكون معناه: وينذرونكم مصيركم إلى هذا اليوم».", "mawaqif": [{"taliq": 5656, "mi": 0, "aya": 71, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 264", "qawl": "", "nass": "{وينذرونكم لقاء يومكم هذا} يقول: وينذرونكم ما تلقون في يومكم هذا. وقد يحتمل أن يكون معناه: وينذرونكم مصيركم إلى هذا اليوم", "qawaid": [], "tabi": ""}]}], "73": [{"id": 5657, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 270) غير قول مجاهد.", "mawaqif": []}, {"id": 5658, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 416) أن قوله: {سلام عليكم} تحية، ثم ذكر فيها احتمالًا آخر، فقال: «ويحتمل أن يريد أنهم قالوا لهم: سلام عليكم وأمنة لكم».", "mawaqif": [{"taliq": 5658, "mi": 0, "aya": 73, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 416", "qawl": "", "nass": "ويحتمل أن يريد أنهم قالوا لهم: سلام عليكم وأمنة لكم", "qawaid": [], "tabi": ""}]}]}, "athar": {"67601": {"num": 67601, "aya": 67, "qail": "عبد الله", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله، قال: أتى النبيَّ صلى الله عليه وسلم رجلٌ من أهل الكتاب، فقال: يا أبا القاسم، بلغك أنّ الله يحمل الخلائق على إصبع، والأرضين على إصبع، والشجر على إصبع، والثَّرى على إصبع، ثم يقول: أنا الملك؟ فضحك رسولُ الله صلى الله عليه وسلم حتى بدتْ نواجذه؛ فأنزل الله: {وما قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ} الآية."}, "67604": {"num": 67604, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق أبي الضحى- قال: مرَّ يهوديٌّ برسول الله صلى الله عليه وسلم وهو جالس، فقال: كيف تقول -يا أبا القاسم- إذا وضع الله السماوات على ذِه -وأشار بالسبابة-، والأرضين على ذِه، والجبال على ذِه، والماء على ذِه، وسائر الخلق على ذِه. كل ذلك يشير بأصابعه؛ فأنزل الله: {وما قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ}."}, "67605": {"num": 67605, "aya": 67, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن سعيد بن جُبير -من طريق جعفر- قال: تكلّمتِ اليهودُ في صفة الرّب، فقالوا ما لم يعلموا، وما لم يروا؛ فأنزل الله: {وما قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ}."}, "67606": {"num": 67606, "aya": 67, "qail": "سعيد", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن سعيد -من طريق محمد- قال: أتى رهطٌ مِن اليهود نبيَّ الله صلى الله عليه وسلم، فقالوا: يا محمد، هذا اللهُ خلَق الخلق، فمَن خلَقه؟ فغضب النبي صلى الله عليه وسلم حتى انتَقَع لونه، ثم ساورهم غضبًا لربه، فجاءه جبريل، فسكّنه، وقال: اخفض عليك جناحك، يا محمد. وجاءه من الله جواب ما سألوه عنه، قال: يقول الله تبارك وتعالى: {قُلْ هُوَ اللَّهُ أحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ ولَمْ يُولَدْ ولَمْ يَكُنْ لَهُ كُفُوًا أحَدٌ} [الإخلاص]. قال: فلما تلاها عليهم النبي صلى الله عليه وسلم قالوا: صِف لنا ربَّك، كيف خَلْقه؟ وكيف عَضُده؟ وكيف ذراعه؟ فغضب النبي صلى الله عليه وسلم أشد من غضبه الأول، ثم ساورهم، فأتاه جبريل، فقال مثل مقالته، وأتاه بجواب ما سألوه عنه، قال: يقول الله: {وما قَدَرُوا اللَّهَ حَقَّ قَدْرِه والأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ القِيامَةِ والسَّماواتُ مَطْوِيّاتٌ بِيَمِينِهِ سُبْحانَهُ وتَعالى عَمّا يُشْرِكُونَ}."}, "67607": {"num": 67607, "aya": 67, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن الحسن البصري، قال: إنّ اليهود نظروا في خلق السماوات والأرض والملائكة، فلمّا فرغوا أخذوا يُقدِّرونه؛ فأنزل الله: {وما قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ}."}, "67610": {"num": 67610, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- قوله: {وما قَدَرُوا اللَّهَ حَقَّ قَدْرِه}، قال: هم الكفار الذين لم يؤمنوا بقدرة الله عليهم، فمَن آمن أنّ الله على كل شيء قدير فقد قدَر الله حقّ قدْره، ومن لم يؤمن بذلك فلم يقدر الله حقَّ قدْره."}, "67614": {"num": 67614, "aya": 67, "qail": "أبي أيوب الأنصاري", "tabaqa": "صحابي", "bab": "", "text": "عن أبي أيوب الأنصاري، قال: أتى رسولَ الله صلى الله عليه وسلم حَبرٌ من اليهود، فقال: أرأيت إذ يقول الله عز وجل في كتابه: {والأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ القِيامَةِ والسَّماواتُ مَطْوِيّاتٌ بِيَمِينِهِ}، فأين الخلْق عند ذلك؟ قال: «هم فيها كرَقْم الكتاب»."}, "67618": {"num": 67618, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق أبي الجوزاء- قال: يطوي اللهُ السماوات السبع بما فيها من الخليقة، والأرضين السبع بما فيها من الخليقة، يطوي ذلك كلَّه بيمينه، يكون ذلك في يده بمنزلة خرْدلة."}, "67619": {"num": 67619, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: يقبض على الأرض والسماوات جميعًا، فما يُرى طرفهما من قبضته، ويده الأخرى يمين."}, "67625": {"num": 67625, "aya": 67, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق عمار بن عمر- في قوله: {والأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ القِيامَةِ}، قال: كأنها جَوزة بقضّها وقضِيضها."}, "67628": {"num": 67628, "aya": 67, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن أبي هريرة، قال: سمعتُ رسولَ الله صلى الله عليه وسلم يقول: «يقبض الله الأرض يوم القيامة، ويطوي السماءَ بيمينه، ويقول: أنا الملك، أين ملوك الأرض؟!»."}, "67633": {"num": 67633, "aya": 67, "qail": "عبد الله بن عمرو", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عمرو، يقول: قال رسول الله صلى الله عليه وسلم: «إنّ المُقسطين عند الله على منابر مِن نور، عن يمين الرحمن عز وجل، وكلتا يديه يمين، الذين يعدلون في حكمهم وأهليهم وما ولُوا»."}, "67634": {"num": 67634, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: قال رسول الله صلى الله عليه وسلم: «أمان لأمتي مِن الغرق إذا ركبوا في السفن: بسم الله الملِك، وما قدروا الله حق قدره والأرض جميعًا قبضته يوم القيامة والسماوات مطويات بيمينه? عما يشركون، بسم الله مجراها ومرساها إن ربي لغفور رحيم»."}, "67635": {"num": 67635, "aya": 67, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق أبي الجوزاء- قال: ما في السماوات السبع والأرضون السبع في يدِ الله عز وجل إلا كخرْدلة في يدِ أحدكم."}, "67638": {"num": 67638, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، قال: سمعتُ رسول الله صلى الله عليه وسلم يقول -وعنده طائفة من أصحابه-: «إنّ الله تبارك وتعالى لَمّا فرغ مِن خلْق السماوات والأرض خلق الصُّورِ، فأعطاه إسرافيل، فهو واضعه على فِيه، شاخِصٌ بصره إلى العرش، ينتظر متى يُؤمَر فينفخ فيه». قلت: يا رسول الله، وما الصُّورِ؟ قال: «القرن». قلت: فكيف هو؟ قال: «عظيم، والذي بعثني بالحق، إن عِظَم دارَةٍ فيه كعرْض السماوات والأرض، فينفخ فيه النفخة الأولى، فيَصعق من في السماوات ومن في الأرض، ثم يُنفخ فيه أخرى {فَإذا هُمْ قِيامٌ يَنْظُرُونَ} لرب العالمين، فيأمر الله إسرافيل في النفخة الأولى أن يمُدّها ويُطوِّلها فلا يفتر، وهو الذي يقول الله: {وما يَنْظُرُ هَؤُلاءِ إلّا صَيْحَةً واحِدَةً ما لَها مِن فَواق} [ص: 15]، فيُسَيِّر اللهُ الجبالَ فتكون سرابًا، وترتجّ الأرضُ بأهلها رجًّا، فتكون كالسفينة المُوثَقة في البحر تضربها الأمواج، تكفَّأ بأهلها كالقنديل المعلّق بالعرش، ترجرجه الأرواح، وهي التي يقول الله: {يَوْمَ تَرْجُفُ الرّاجِفَةُ تَتْبَعُها الرّادِفَةُ قُلُوبٌ يَوْمَئِذٍ واجِفَةٌ} [النازعات: 8] فيَمِيدُ الناس على ظهرها، وتَذْهل المراضع، وتضع الحوامل، وتشيب الولدان، وتطير الشياطين هارِبةً مِن الفزع، حتى تأتي الأقطار، فتلقاها الملائكة، فتضرب وجوهها فترجع، ويتولي الناس مُدبرين، ينادي بعضُهم بعضًا، وهو قوله: {يَوْمَ تُوَلُّونَ مُدْبِرِينَ ما لَكُمْ مِنَ اللَّهِ مِن عاصِمٍ} [غافر: 33]، [وقوله: {يَوْمَ التَّنادِ} [غافر: 32] يوم يُنادي بعضُهم بعضًا، فبينما هم على ذلك إذ تصدّعت الأرض، كل صِدعٍ مِن قُطر إلى قُطر، فرأوا أمرًا عظيمًا لم يروا مثله، وأخذهم لذلك مِن الكَرْب والهول ما الله به عليم، ثم نظروا إلى السماء فإذا هي كالمُهل، ثم انشقت وانتثرت نجومها، وخسفَ شمسها وقمرها». فقال رسول الله صلى الله عليه وسلم: «والأمواتُ لا يعلمون شيئًا مِن ذلك». فقلتُ: يا رسول الله، فمَن استثنى الله حين يقول: {فَصَعِقَ مَن فِي السَّماواتِ ومَن فِي الأَرْضِ إلّا مَن شاءَ اللَّهُ}؟ قال: «أولئك الشهداء، وإنما يصل الفزع إلى الأحياء، وهم أحياء عند ربهم يُرزقون، ووقاهم الله فزع ذلك اليوم، وآمنهم منه، وهو الذي يقول الله: {يا أيُّها النّاسُ اتَّقُوا رَبَّكُمْ إنَّ زَلْزَلَةَ السّاعَةِ شَيْءٌ عَظِيمٌ} إلى قوله: {ولَكِنَّ عَذابَ اللَّهِ شَدِيدٌ} [الحج: 1 - 2] فينفخ نفخة الصعق، فيصعق أهل السماوات وأهل الأرض {إلّا مَن شاءَ اللَّهُ}، فإذا هم خمود، ثم يجيء مَلك الموت إلى الجبّار فيقول: يا رب، قد مات أهلُ السماوات وأهل الأرض إلا من شئت. فيقول -وهو أعلم-: فمَن بقي؟ فيقول: يا رب، بقيتَ أنت الحيُّ الذي لا يموت، وبقي حَمَلةُ عرشك، وبقي جبريل وميكائيل وإسرافيل، وبقيتُ أنا. فيقول الله: ليمتْ جبريل وميكائيل وإسرافيل. ويُنطِق اللهُ العرشَ، فيقول: يا ربّ، تميت جبريل وميكائيل وإسرافيل؟! فيقول الله له: اسكت، إني كتبتُ الموت على مَن كان تحت عرشي. فيموتون، ثم يأتي مَلك الموت إلى الجبّار، فيقول: يا رب، قد مات جبريل وميكائيل وإسرافيل. فيقول الله عز وجل -وهو أعلم-: فمن بقي؟ فيقول: يا رب، بقيتَ أنت الحي الذي لا يموت، وبقي حملة عرشك، وبقيتُ أنا. فيقول الله له: ليمُت حملة عرشي. فيموتون، ويأمر الله العرش، فيقبض الصُّورَ، ثم يأتي ملك الموت الرّب فيقول: يا ربّ، قد مات حملة عرشك. فيقول الله -وهو أعلم-: فمن بقي؟ فيقول: يا ربّ، بقيتَ أنت الحي الذي لا يموت، وبقيتُ أنا. فيقول الله له: أنت خلْق من خلقي، خلقتُك لِما رأيتَ، فمُت. فيموت، فإذا لم يبق إلا الله الواحد القهار الصمد الذي لم يلد ولم يولد، كان آخرًا كما كان أولًا، طوى السماوات والأرض كطي السِّجل للكتاب، ثم قال: دحاهما، ثم تلقّفهما، ثم قال: أنا الجبار. ثلاث مرات، ثم هتف بصوته: لِمَن الملك اليوم؟ لمن الملك اليوم؟ لمن الملك اليوم؟ فلا يجيبه أحد. ثم يقول لنفسه: لله الواحد القهار. {يَوْمَ تُبَدَّلُ الأَرْضُ غَيْرَ الأَرْضِ والسَّماواتُ} [إبراهيم: 48]، فبسطَها وسطَحها، ثم مدّها مد الأديم العكاظي، {لا تَرى فِيها عِوَجًا ولا أمْتًا} [طه: 107]، ثم يزجر الله الخلْق زجرةً واحدة، فإذا هم في هذه المُبدَّلة، مَن كان في بطنها كان في بطنها، ومَن كان على ظهرها كان على ظهرها، ثم يُنزل الله عليكم ماءً مِن تحت العرش، فيأمر الله السماءَ أن تُمطِر، فتُمطر أربعين يومًا، حتى يكون الماءُ فوقكم اثني عشر ذراعًا، ثم يأمر الله الأجسادَ أن تَنبت، فتنبت نبات الطراثيث وكنبات البقْل، حتى إذا تكاملت أجسامهم، وكانت كما كانت، قال الله: لِيَحيى حَمَلَةُ العرش. فيحيون، ويأمر الله إسرافيل فيأخذ الصُّورَ، فيضعه على فيه، ثم يقول الله: لِيَحيى جبريل وميكائيل. فيحييان، ثم يدعو الله بالأرواح، فيؤتى بها توهَّج أرواح المؤمنين نورًا والأخرى ظلمة، فيقبضها الله جميعًا، ثم يلقيها في الصُّورِ، ثم يأمر إسرافيل أن ينفخ نفخة البعث، فتخرج الأرواح كأنها النَّحل قد ملأت ما بين السماء والأرض، فيقول: وعِزَّتي وجلالي، لَيَرْجِعَنَّ كلُّ روح إلى جسده. فتدخل الأرواح في الأرض إلى الأجساد، فتدخل في الخياشيم، ثم تمشي في الأجساد كما يمشي السُّمُّ في اللديغ، ثم تنشق الأرض عنكم، وأنا أول مَن تنشق عنه الأرض، فتخرجون منها سِراعًا إلى ربكم تنسلون، {مُهْطِعِينَ إلى الدّاعِ يَقُولُ الكافِرُونَ هَذا يَوْمٌ عَسِرٌ} [القمر: 8] حُفاة عُراة غُلْفًا غُرلًا. فبينما نحن وقوف إذ سمعنا حِسًّا مِن السماء شديدًا، فينزل أهلُ سماء الدنيا بمثلي مَن في الأرض من الجن والإنس، حتى إذا دَنَوا مِن الأرض أشرقتِ الأرضُ بنورهم، ثم ينزل أهل السماء الثانية بمثلي مَن نزل من الملائكة، ومثلي مَن فيها من الجن والإنس، حتى إذا دَنوا من الأرض أشرقت الأرض بنورهم، وأخذوا مصافّهم، ثم ينزل أهلُ السماء الثالثة بمثلي مَن نزل من الملائكة، ومثلي مَن فيها من الجن والإنس، حتى إذا دَنوا من الأرض أشرقت الأرض بنورهم، وأخذوا مصافَّهم، ثم ينزلون على قَدْر ذلك مِن التضعيف إلى السماوات السبع، ثم ينزل الجبار {فِي ظُلَلٍ مِنَ الغَمامِ والمَلائِكَةُ} [البقرة: 210]، يحمل عرشه يومئذ ثمانية، وهم اليوم أربعة، أقدامهم على تُخُوم الأرض السفلى، والأرضون والسماوات إلى حُجَزهم، والعرش على مناكبهم، لهم زَجَلٌ بالتسبيح فيقولون: سبحان ذي العِزّة والجبروت، سبحان ذي الملك والملكوت، سبحان الحيِّ الذي لا يموت، سبحان الذي يُميت الخلائق ولا يموت، سُبُّوحٌ قُدُّوس ربُّ الملائكة والروح، سبحان ربنا الأعلى الذي يميت الخلائق ولا يموت. فيضع عرشه حيث يشاء من الأرض، ثم يهتف بصوته فيقول: يا معشر الجن والإنس، إنِّي قد أنصَتُّ لكم منذ يوم خلقتكم إلى يومك هذا؛ أسمع قولكم، وأُبصر أعمالكم، فأنصِتوا لي، فإنما هي أعمالكم وصحفكم تُقرأ عليكم، فمَن وجد خيرًا فليحمد الله، ومَن وجد غير ذلك فلا يَلُومَنَّ إلا نفسه. ثم يأمر اللهُ جهنمَ، فيخرج منها عُنُق ساطِع مظلم، ثم يقول: {ألَمْ أعْهَدْ إلَيْكُمْ يا بَنِي آدَمَ أنْ لا تَعْبُدُوا الشَّيْطانَ إنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ وأَنِ اعْبُدُونِي هَذا صِراطٌ مُسْتَقِيمٌ} [يس: 60 - 61]، {وامْتازُوا اليَوْمَ أيُّها المُجْرِمُونَ} [يس: 59] فيَمِيز بين الناس، وتجثو الأمم، قال: {وتَرى كُلَّ أُمَّةٍ جاثِيَةً كُلُّ أُمَّةٍ تُدْعى إلى كِتابِها} [الجاثية: 28]، ويقفون موقفًا واحدًا مقدار سبعين عامًا لا يُقضى بينهم، فيبكون حتى تنقطع الدموعُ، ويدمعون دمًا، ويعرقون عرقًا حتى يبلغ ذلك منهم أن يُلْجمهم العرق وأن يبلغ الأذقانَ منهم، فيصيحون ويقولون: مَن يشفع لنا إلى ربِّنا؛ فيقضي بيننا؟ فيقولون: ومَن أحقُّ بذلك مِن أبيكم آدم؟ فيطلبون ذلك إليه، فيأبى ويقول: ما أنا بصاحب ذلك. ثم يستقْرُون الأنبياء نبيًّا نبيًّا، كلما جاءوا نبيًّا أبى عليهم». قال رسول الله صلى الله عليه وسلم: «حتى يأتوني، فأنطلِق حتى آتي الفَحْص، فأخرّ ساجدًا». قال: أبو هريرة: يا رسول الله، وما الفَحْص؟ قال: «قُدام العرش، حتى يبعث الله إلَيَّ ملَكًا، فيأخذ بعَضُدي، فيرفعني، فيقول لي: يا محمد. فأقول: نعم، يا ربِّ. ما شأنك؟ -وهو أعلم بي- فأقول: يا ربِّ، وعدتني الشفاعة؛ فشفِّعني في خلقك، فاقْضِ بينهم. قال: قد شفّعتُك، وأقضي بينهم». قال: قال رسول الله صلى الله عليه وسلم: «فأرجع، فأقف مع الناس، فيقضي الله بين الخلائق، فيكون أول ما يُقضى فيه في الدماء، ويأتي كل مَن قُتل في سبيل الله يحمل رأسه، وتَشْخُبُ أوداجه دمًا، فيقولون: يا ربَّنا، قتَلَنا فلان وفلان. فيقول الله -وهو أعلم-: لِمَ قُتِلتم؟ فيقولون: يا ربنا، قُتِلنا لتكون العِزَّة لك. فيقول الله لهم: صدقتم. فيجعل الله لوجوههم نورًا مثل نور الشمس، ثم تشيّعهم الملائكة إلى الجنة، ويأتي مَن كان قُتِل على غير ذلك، يحمل رأسه وتَشْخُب أوداجه، فيقولون: يا ربنا، قتَلَنا فلان وفلان. فيقول: لِمَ؟ -وهو أعلم- فيقول: لِتكون العِزَّة لي. فيقول الله: تَعِست. ثم ما يبقى نفس قَتلها إلا قُتِل بها، ولا مظلمة ظَلمها إلا أُخِذ بها، وكان في مشيئة الله؛ إن شاء عذّبه، وإن شاء رحمه، ثم يقضي الله بين مَن بقي مِن خلْقه حتى لا يبقى مظلمة لأحد عند أحد إلا أخذها الله للمظلوم من الظالم، حتى إنّه ليكلَّف يومئذ شائب اللبن للبيع، الذي كان يشوب اللبن بالماء ثم يبيعه، فيُكلّف أن يُخلِّص الماء من اللبن. فإذا فرغ الله مِن ذلك نادى نداءً أسمع الخلائق كلهم: ألا لِيلحقْ كلُّ قوم بآلهتهم وما كانوا يعبدون من دون الله. فلا يبقى أحدٌ عبد مِن دون الله شيئًا إلا مُثِّلَت له آلهته بين يديه، ويُجعل يومئذ مَلَك من الملائكة على صورة عُزَير، ويُجعل مَلَك من الملائكة على صورة عيسى، فيتبع هذا اليهود، وهذا النصارى، ثم يعود بهم آلهتهم إلى النار، فهي التي قال الله: {لَوْ كَانَ هَؤُلَاءِ آلِهَةً مَا وَرَدُوهَا وَكُلٌّ فِيهَا خَالِدُونَ} [الأنبياء: 99]، فإذا لم يبق إلا المؤمنون وفيهم المنافقون، فيقول: يا أيها الناس، ذهب الناسُ، فالحقوا بآلهتكم وما كنتم تعبدون. فيقولون: واللهِ، ما لنا إله إلا الله، وما كنا نعبد غيره. فيقال لهم الثانية، والثالثة، فيقولون مثل ذلك، فيقول: أنا ربُّكم، فهل بينكم وبين ربكم آيةٌ تعرفونه بها؟ فيقولون: نعم. فيكشِف عن ساق، ويريهم ما شاء الله أن يريهم، فيعرفون أنَّه ربهم، فيخرّون له سُجّدًا لوجوههم، ويخرّ كلُّ منافق على قفاه؛ يجعل الله أصلابهم كصَيَاصِيّ البقر، ثم يأذن الله لهم، فيرفعون رؤوسهم، ويُضرَب الصِّراط بين ظهراني جهنم كدّقة الشعر، أو كحدّ السيف، عليه كلاليب وخطاطيف وحَسَكٌ كحَسَك السَّعْدان، دونه جسر دَحْضٌ مَزَلَّةٌ، فيمرّون كطرْف العين، وكلمْح البرق، وكمرِّ الريح، وكجياد الخيل، وكجياد الركاب، وكجياد الرجال؛ فناجٍ سالم، وناجٍ مخدوش، ومَكْدُوشٌ على وجهه في جهنم، فإذا أفضى أهلُ الجنة إلى الجنة فدخلوها، فوالذي بعثني بالحق، ما أنتم في الدنيا بأعرف بأزواجكم ومساكنكم مِن أهل الجنة بأزواجهم ومساكنهم إذا دخلوا الجنة، فيدخل كلُّ رجل منهم على اثنتين وسبعين زوجة مِمّا ينشئ الله في الجنة، واثنتين آدميتين مِن ولد آدم لهما فضلٌ على مَن أنشأ الله؛ لعبادتهما في الدنيا، فيدخل على الأولى منهنَّ في غُرفة مِن ياقوتة، على سرير من ذهب، مُكلّل باللؤلؤ، عليه سبعون زوجًا مِن سُندس وإستبرق، ثم إنه يضع يده بين كتفيها، فينظر إلى يدها مِن صدرها، ومن وراء ثيابها وجلدها ولحمها، وإنه لينظر إلى مُخِّ ساقها كما ينظر أحدُكم إلى السلك في الياقوتة، كبدها له مرآة، وكبده لها مرآة، فبينما هو عندها لا يملُّها ولا تملّه، ولا يأتيها مرة إلا وجدها عذراء، لا يفتران ولا يألمان، فبينما هو كذلك إذ نُودِي فيُقال له: إنّا قد عرفنا أنك لا تَمَلّ ولا تُملّ، وإنّ لك أزواجًا غيرها. فيخرج فيأتيهنَّ واحدة واحدة، كلما جاء واحدةً قالت له: واللهِ، ما أرى في الجنة شيئًا أحسن منك، ولا شيئًا في الجنة أحب إلَيَّ منك. قال: وإذا وقع أهلُ النار في النار وقع فيها خَلْق مِن خَلْق الله، أوْبقَتهم أعمالهم، فمنهم مَن تأخذه النار إلى ركبتيه، ومنهم مَن تأخذه النار إلى حَقْوَيه، ومنهم من تأخذه النار في جسده كله إلا وجهه؛ حرّم الله صورهم على النار، فينادون في النار فيقولون: مَن يشفع لنا إلى ربنا حتى يُخرجنا مِن النار؟ فيقولون: ومَن أحقُّ بذلك مِن أبيكم آدم؟! فينطلق المؤمنون إلى آدم، فيقولون: خلقك اللهُ بيده، ونَفخَ فيك مِن روحه، وكلّمك قِبَلًا. فيذكر آدمُ ذنبَه، فيقول: ما أنا بصاحب ذلك، ولكن عليكم بنوح؛ فإنّه أول رسل الله. فيؤتى نوح، ويُطلب ذلك إليه، فيذكر ذنبًا، ويقول: ما أنا بصاحب ذلك، ولكن عليكم بإبراهيم؛ فإنّ الله اتخذه خليلًا. فيؤتى إبراهيم، فيُطلب ذلك إليه، فيذكر ذنبًا، فيقول: ما أنا بصاحب ذلك، ولكن عليكم بموسى؛ فإن الله قرّبه نجيًّا وكلّمه، وأنزل عليه التوراة. فيؤتى موسى، فيُطلب ذلك إليه، فيذكر ذنبًا، ويقول: ما أنا بصاحب ذلك، ولكن عليكم بروح الله وكلمته، عيسى ابن مريم. فيؤتى عيسى ابن مريم، فيُطلب ذلك إليه، فيقول: ما أنا بصاحب ذلك، ولكن عليكم بمحمد صلى الله عليه وسلم». قال رسول الله صلى الله عليه وسلم: «فيأتوني، ولي عند ربي ثلاث شفاعات وعدنيهن، فأنطلق حتى آتيَ باب الجنة، فآخذ بحلقة الباب، فاستفتح، فيُفتح لي، فأخرّ ساجدًا، فيأذن لي من حمده وتمجيده بشيء ما أذن به لأحد من خلْقه، ثم يقول: ارفع رأسك، يا محمد، اشفع تُشفّع، وسل تُعطه. فإذا رفعتُ رأسي قال لي -وهو أعلم-: ما شأنك؟ فأقول: يا رب، وعدتني الشفاعة؛ فشَفِّعْني. فأقول: يا رب، مَن وقع في النار مِن أمتي. فيقول الله: أخْرِجوا مَن عرفتم صورته. فيخرج أولئك حتى لا يبقى منهم أحد، ثم يأذن الله في الشفاعة، فلا يبقى نبيٌّ ولا شهيدٌ إلا شفع، فيقول الله: أخرِجوا مَن وجدتم في قلبه زِنة دينار مِن خير. فيخرج أولئك حتى لا يبقى منهم أحدٌ، ثم يشفع الله، فيقول: أخرِجوا مَن وجدتم في قلبه زِنَة ثلثي دينار. ثم يقول: نصف دينار. ثم يقول: ثلث دينار. ثم يقول: ربع دينار. ثم يقول: قيراط. ثم يقول: مثقال حبة. فيخرج أولئك حتى لا يبقى منهم أحدٌ، وحتى لا يبقى في النار مَن عمل خيرًا قط، ولا يبقى أحدٌ له شفاعة إلا شُفِّع، حتى إنّ إبليس لَيتطاولُ لِما يرى مِن رَحْمَة اللَّه رجاءَ أن يُشفع له، ثم يقول الله: بقيتُ وأنا أرحم الراحمين. فيقبض قبضةً، فيخرج منها ما لا يحصيه غيره، فيبثّهم على نهرٍ يُقال له: نهر الحيوان، فينبتون فيه كما تنبت الحِبَّةُ في حَمِيلِ السَّيْلِ، فما يلي الشمس أُخَيْضِر، وما يلي الظِّل أُصَيْفِر، فينبتون كالذَّرّ، مكتوب في رقابهم: الجهنميون عتقاء الرحمن. لم يعملوا لله خيرًا قط -يقول: مع التوحيد-، فيمكثون في الجنة ما شاء الله وذلك الكتاب في رقابهم، ثم يقولون: يا ربنا، امحُ عنا هذا الكتاب. فيمحوه عنهم»."}, "67645": {"num": 67645, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن أبي هريرة، قال: قال رسول الله صلى الله عليه وسلم: «ما طَرَف صاحبُ الصُّور مُذ وُكِّل به، مستعدًّا ينظر نحو العرش مخافة أن يُؤمر بالصيحة قبل أن يرتدّ إليه طرْفُه، كأنّ عينيه كوكبان دُرِّيّان»."}, "67655": {"num": 67655, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، قال: اسْتَبَّ رجلان؛ رجل من المسلمين ورجل من اليهود، قال المسلم: والذي اصطفى محمدًا على العالمين. فقال اليهودي: والذي اصطفى موسى على العالمين. فرفع المسلم يده عند ذلك، فلطم وجه اليهودي، فذهب اليهوديُّ إلى النبي صلى الله عليه وسلم، فأخبره بما كان مِن أمره وأمرِ المسلم، فدعا النبيُّ صلى الله عليه وسلم المسلمَ، فسأله عن ذلك، فأخبره، فقال النبيُّ صلى الله عليه وسلم: «لا تخيِّروني على موسى؛ فإنّ الناس يَصعقون يوم القيامة، فأصعق معهم، فأكون أول مَن يُفيق، فإذا موسى باطِشٌ جانب العرش، فلا أدري أكان فيمن صَعق فأفاق قبلي، أو كان مِمَّن استثنى الله»."}, "67657": {"num": 67657, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، عن النبيّ صلى الله عليه وسلم، قال: «سألتُ جبريلَ عن هذه الآية: {ونُفِخَ فِي الصُّورِ فَصَعِقَ مَن فِي السَّماواتِ ومَن فِي الأَرْضِ إلّا مَن شاءَ اللَّهُ}، مَن الذين لم يشأِ اللهُ أن يَصعَقهم؟ قال: هم الشهداء، متقلّدون أسيافهم حول عرشه، تتلقاهم الملائكة يوم القيامة إلى المحشر بِنَجائبَ من ياقوت، أزِمَّتُها الدُّر، بِرَحائِلِ السُّندس والإستبرق، نِمارُها ألين من الحرير، مدّ خطاها مدّ أبصار الرجال، يسيرون في الجنة، يقولون عند طول النُّزهة: انطلِقوا بنا إلى ربِّنا ننظر كيف يقضي بين خلْقه. يضحك إليهم إلهي، وإذا ضحك إلى عبدٍ في موطن فلا حساب عليه»."}, "67662": {"num": 67662, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هُريْرة، {فَصَعِقَ مَن فِي السَّماواتِ ومَن فِي الأَرْضِ إلّا مَن شاءَ اللَّهُ}، قال: هم الشهداء، ثنيَّة الله."}, "67152": {"num": 67152, "aya": 6, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {يَخْلُقُكُمْ فِي بُطُونِ أُمَّهاتِكُمْ خَلْقًا مِن بَعْدِ خَلْقٍ}، قال: خلْقًا في البطون، من بعد الخلْق الأول الذي خلَقهم في ظهر آدم."}, "67665": {"num": 67665, "aya": 68, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير -من طريق ذي حُجْرٍ اليَحْمَديّ- في قوله: {إلّا مَن شاءَ اللَّهُ}، قال: هم الشهداء، ثنيَّة الله، متقلدي السيوف حول العرش."}, "67673": {"num": 67673, "aya": 68, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {فَصَعِقَ} قال: مات {إلّا مَن شاءَ اللَّهُ} قال: جبريل، وميكائيل، وإسرافيل، ومَلك الموت."}, "67162": {"num": 67162, "aya": 6, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {فِي ظُلُماتٍ ثَلاثٍ}، قال: المشيمة في الرّحم، والرّحم في البطن."}, "67676": {"num": 67676, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، قال: قال رسول الله صلى الله عليه وسلم: «بين النفختين أربعون». قالوا: يا أبا هريرة، أربعون يومًا؟ قال: أبَيْتُ. قالوا: أربعون شهرًا؟ قال: أبَيْتُ. قالوا: أربعون عامًا؟ قال: أبيتُ. «ثم يُنزل الله من السماء ماءً، فيَنبُتون كما ينبت البقْل، وليس مِن الإنسان شيء إلا يبلى، إلا عظْمًا واحدًا، وهو عَجْبُ الذَّنَب، ومنه يُركّب الخلْق يوم القيامة»."}, "67677": {"num": 67677, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، عن النبي صلى الله عليه وسلم، قال: «يُنفخ في الصُّور -والصُّور: كهيئة القرْن-، فَصَعِقَ مَن في السماوات ومَن في الأرض، وبين النفختين أربعون عامًا، فيمطر الله في تلك الأربعين مطرًا، فيَنبُتون مِن الأرض كما ينبت البقْل، ومِن الإنسان عظْم لا تأكله الأرض؛ عَجْب ذَنَبه، ومنه يُركَّب جسده يوم القيامة»."}, "67166": {"num": 67166, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- {إنْ تَكْفُرُوا فَإنَّ اللَّهَ غَنِيٌّ عَنْكُمْ}: يعني: الكفار الذين لم يُرِد الله أن يطهِّر قلوبهم، فيقولوا: لا إله إلا الله."}, "67678": {"num": 67678, "aya": 68, "qail": "أبي هريرة", "tabaqa": "صحابي", "bab": "", "text": "عن أبي هريرة، عن النَّبِيّ صلى الله عليه وسلم قال: «كل ابن آدم تأكله الأرض إلا عَجْب الذَّنب، منه يَنبُت، ويرسل الله ماء الحياة، فيَنبُتون منه نبات الخَضِر، حتى إذا خرجت الأجساد، أرسل الله الأرواح، فكان كل روح أسرع إلى صاحبه من الطَّرْف، ثم يُنفخ في الصُّورِ {فَإذا هُمْ قِيامٌ يَنْظُرُونَ}»."}, "67168": {"num": 67168, "aya": 7, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- قال: {ولا يَرْضى لِعِبادِهِ الكُفْرَ} وهم عباده المخلصون الذين قال: {إنَّ عِبادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطانٌ إلّا مَنِ اتَّبَعَكَ مِنَ الغاوِينَ} [الحجر: 42]، فألزمهم شهادة أن لا إله إلا الله، وحبّبها إليهم."}, "67172": {"num": 67172, "aya": 7, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {ولا يَرْضى لِعِبادِهِ الكُفْرَ}، قال: لا يرضى لعباده المؤمنين أن يكفروا."}, "67685": {"num": 67685, "aya": 68, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {ثُمَّ نُفِخَ فِيهِ أُخْرى} قال: في الصُّور، وهي نفخة البعث، {فَإذا هُمْ قِيامٌ يَنْظُرُونَ} قال: حين يُبعثون."}, "67174": {"num": 67174, "aya": 7, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّي -من طريق أسباط- {وإنْ تَشْكُرُوا يَرْضَهُ}، قال: إن تطيعوا يرضه لكم."}, "67177": {"num": 67177, "aya": 7, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّي -من طريق أسباط- {ولا تَزِرُ وازِرَةٌ وِزْرَ أُخْرى}، قال: لا يُؤخَذ أحدٌ بذنب أحد."}, "67692": {"num": 67692, "aya": 69, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "وإسماعيل السّدّيّ: {وأَشْرَقَتِ الأَرْضُ بِنُورِ رَبِّها} بعدل ربها."}, "67694": {"num": 67694, "aya": 69, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّي -من طريق أسباط- {وأَشْرَقَتِ الأَرْضُ}، قال: أضاءت."}, "67183": {"num": 67183, "aya": 8, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {ثُمَّ إذا خَوَّلَهُ نِعْمَةً مِنهُ}: إذا أصابته عافية أو خير."}, "67185": {"num": 67185, "aya": 8, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {نَسِيَ}، يقول: ترك، هذا في الكافر خاصة."}, "67697": {"num": 67697, "aya": 69, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {ووُضِعَ الكِتابُ}، قال: الحساب."}, "67187": {"num": 67187, "aya": 8, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {وجَعَلَ لِلَّهِ أنْدادًا}، قال: الأنداد من الرجال، يطيعونهم في معاصي الله."}, "67699": {"num": 67699, "aya": 69, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، {وجِيءَ بِالنَّبِيِّينَ والشُّهَداءِ}، قال: النبيّون: الرسل، والشهداء: الذين يشهدون بالبلاغ، ليس فيهم طعّان ولا لعّان."}, "67700": {"num": 67700, "aya": 69, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق على- {وجِيءَ بِالنَّبِيِّينَ والشُّهَداءِ}، قال: يشهدون بتبليغ الرسالة، وبتكذيب الأمم إيّاهم."}, "67702": {"num": 67702, "aya": 69, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {وجِيءَ بِالنَّبِيِّينَ والشُّهَداء}: الذين استُشهدوا في طاعة الله."}, "67211": {"num": 67211, "aya": 10, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- {لِلَّذِينَ أحْسَنُوا فِي هَذِهِ الدُّنْيا حَسَنَةٌ}، قال: العافية، والصِّحَّة."}, "67225": {"num": 67225, "aya": 10, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {إنَّما يُوَفّى الصّابِرُونَ أجْرَهُمْ بِغَيْرِ حِسابٍ}، قال: في الجنة."}, "67336": {"num": 67336, "aya": 24, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {أفَمَن يَتَّقِي بِوَجْهِهِ سُوءَ العَذابِ يَوْمَ القِيامَةِ}، قال: يُجرّ على وجهه في النار، وهو مثل قوله: {أفَمَن يُلْقى فِي النّارِ خَيْرٌ أمْ مَن يَأْتِي آمِنًا يَوْمَ القِيامَةِ} [فصلت: 40]."}, "67375": {"num": 67375, "aya": 31, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر -من طريق سعيد- قال: نزلت علينا الآية: {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ} وما ندري ما تفسيرها -ولفظ عَبد بن حُمَيد: وما ندري فيم نزلت-، قلنا: ليس بيننا خصومة، فما التخاصم؟! حتى وقعت الفتنة، فقلنا: هذا الذي وعدنا ربُّنا أن نختصم فيه."}, "67376": {"num": 67376, "aya": 31, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر -من طريق سعيد- قال: لقد لبثنا بُرْهَةً مِن دهرنا ونحن نرى أنّ هذه الآية نزلت فينا وفي أهل الكتابين مِن قبلنا: {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ}. قلنا: كيف نختصم ونبيُّنا واحدٌ وكتابُنا واحد؟! حتى رأيتُ بعضَنا يضرب وجوهَ بعضٍ بالسيف، فعرفتُ أنها فينا نزلت."}, "67377": {"num": 67377, "aya": 31, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عمر -من طريق سعيد- قال: عِشنا بُرهةً مِن دهرنا وما نرى هذه الآية نزلتْ فينا: {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ} فقلتُ: لم نختصم؟! أمّا نحن فلا نعبد إلا الله، وأمّا ديننا فالإسلام، وأمّا كتابنا فالقرآن، لا نغيّره أبدًا، ولا نحرِّف الكتاب، وأمّا قِبلتنا فالكعبة، وأمّا حَرامنا -أو حَرمنا- فواحد، وأمّا نبينا فمحمد صلى الله عليه وسلم، فكيف نختصم؟! حتى كَفَحَ بعضُنا وجهَ بعض بالسيف، فعرفتُ أنها نزلت فينا."}, "67379": {"num": 67379, "aya": 31, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النَّخْعيّ -من طريق ابن عون- قال: أُنزلت هذه الآية: {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ} قالوا: وما خصومتنا ونحن إخوان؟! فلما قُتل عثمان بن عفان قالوا: هذه خصومة ما بيننا."}, "67380": {"num": 67380, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ}، يقول: يخاصم الصادقُ الكاذبَ، والمظلومُ الظالمَ، والمهتدي الضالَّ، والضعيف المستكبر."}, "67381": {"num": 67381, "aya": 31, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحِي -من طريق الربيع بن أنس- في قوله: {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ}، قال: هم أهل القِبلة."}, "67382": {"num": 67382, "aya": 31, "qail": "أبي العالية الرياحي", "tabaqa": "تابعي", "bab": "", "text": "عن أبي العالية الرِّياحِي -من طريق الربيع بن أنس- {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ}، قال: في مظالمهم بينهم."}, "67386": {"num": 67386, "aya": 31, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ثُمَّ إنَّكُمْ يَوْمَ القِيامَةِ عِنْدَ رَبِّكُمْ تَخْتَصِمُونَ}، قال: أهل الإسلام، وأهل الكفر."}, "67390": {"num": 67390, "aya": 31, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: يختصم الناس يوم القيامة، حتى يختصم الروح مع الجسد، فتقول الروح للجسد: أنتَ فعلتَ. ويقول الجسد للروح: أنتِ أمرتِ، وأنتِ سوّلتِ. فيبعث الله تعالى ملَكًا فيقضي بينهما، فيقول لهما: إن مَثلكما كمَثل رجل مُقعَد بصير، وآخر ضرير، دخلا بستانًا فقال المُقعد للضرير: إنِّي أرى ههنا ثمارًا، ولكن لا أصِلُ إليها، فقال له الضرير: اركبني فتناولها. فركبه فتناولها، فأيهما المعتدي؟ فيقولان: كلاهما. فيقول لهما الملَك: فإنكما قد حكمتما على أنفسكما، يعني: أن الجسد للروح كالمطيّة وهو راكبه."}, "67397": {"num": 67397, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {والَّذِي جاءَ بِالصِّدْقِ} يعني: بلا إله إلا الله، {وصَدَّقَ بِهِ} يعني: رسول الله صلى الله عليه وسلم."}, "67400": {"num": 67400, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {والَّذِي جاءَ بِالصِّدْقِ} قال: رسول الله صلى الله عليه وسلم، {وصَدَّقَ بِهِ} قال: علي بن أبي طالب."}, "67401": {"num": 67401, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- أنه كان يقرأ: {والَّذِي جاءَ بِالصِّدْقِ وصَدَّقَ بِهِ}، قال: هم أهل القرآن، يجيئون بالقرآن يوم القيامة يقولون: هذا ما أعطيتمونا قد اتَّبعنا ما فيه."}, "67402": {"num": 67402, "aya": 33, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- {والذي جاء بالصدق وصدق به}، قال: محمد صلى الله عليه وسلم."}, "67406": {"num": 67406, "aya": 33, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {والَّذِي جاءَ بِالصِّدْقِ} قال: هو النبي صلى الله عليه وسلم {بِالصِّدْقِ} أي: القرآن، {وصَدَّقَ بِهِ} قال: المؤمنون."}, "67407": {"num": 67407, "aya": 33, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {والَّذِي جاءَ بِالصِّدْقِ} قال: هو جبريل، {وصَدَّقَ بِهِ} قال: هو النبي صلى الله عليه وسلم."}, "67410": {"num": 67410, "aya": 33, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {والَّذِي جاءَ بِالصِّدْقِ}: رسول الله صلى الله عليه وسلم، وصدّق به المسلمون."}, "67411": {"num": 67411, "aya": 33, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {أُولَئِكَ هُمُ المُتَّقُونَ}: يعني: اتقوا الشرك."}, "67444": {"num": 67444, "aya": 42, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدِّيّ -من طريق أسباط- في قوله: {اللَّهُ يَتَوَفّى الأَنْفُسَ حِينَ مَوْتِها} قال: تُقبض الأرواح عند نيام النائم، فيَقبِض روحه في منامه، فتلقى الأرواحُ بعضُها بعضًا؛ أرواحُ الموتى وأرواحُ النيام، فتلتقي، فتساءل. قال: فيُخلّى عن أرواح الأحياء فترجع إلى أجسادها، وتريد الأخرى أن ترجع، فيَحبِس التي قضى عليها الموت، {ويُرْسِلُ الأُخْرى إلى أجَلٍ مُسَمًّى} قال: إلى بقية آجالها."}, "67446": {"num": 67446, "aya": 42, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {اللَّهُ يَتَوَفّى الأَنْفُسَ حِينَ مَوْتِها والَّتِي لَمْ تَمُتْ فِي مَنامِها} قال: فالنوم وفاة، {فَيُمْسِكُ الَّتِي قَضى عَلَيْها المَوْتَ ويُرْسِلُ الأُخْرى} التي لم يقبضها {إلى أجَلٍ مُسَمًّى}."}, "67489": {"num": 67489, "aya": 53, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عمر -من طريق نافع- قال: كُنّا نقول: ما لِمُفتَتنٍ توبةٌ، وما اللهُ بقابلٍ منه شيئًا؛ عرفوا ذلك وآمنوا به وصدّقوا رسوله، ثم رجعوا عن ذلك لبلاء أصابهم، وكانوا يقولونه لأنفسهم. فلمّا قدِم رسولُ الله صلى الله عليه وسلم المدينة أنزل الله فيهم: {قُلْ يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ} الآيات. قال ابنُ عمر: فكتبتُها بيدي، ثم بعثتُ بها إلى هشام بن العاص."}, "67490": {"num": 67490, "aya": 53, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عمر -من طريق نافع- قال: إنّما نزلت هذه الآيات في عيّاش بن أبي ربيعة، والوليد بن الوليد، ونفر من المسلمين كانوا أسلموا، ثم فُتنوا وعُذِّبوا، فافتتنوا، فكنا نقول: لا يقبل الله من هؤلاء صَرفًا ولا عدلًا أبدًا؛ قومٌ أسلموا ثم تركوا دينهم بعذاب عُذِّبوه؟! فنزلت هؤلاء الآيات، وكان عمر بن الخطاب كاتبًا، فكتبها بيده، ثم بعث بها إلى عيّاش والوليد وإلى أولئك النفر، فأسلموا، وهاجروا."}, "67491": {"num": 67491, "aya": 53, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس، قال: أُنزلت: {قُلْ يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ} الآية، في مشركي أهل مكة."}, "67492": {"num": 67492, "aya": 53, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق سعيد بن جُبير-: أنّ ناسًا مِن أهل الشرك كانوا قد قتلوا وأكثروا، وزنَوا وأكثروا، فأَتَوا محمدًا صلى الله عليه وسلم، فقالوا: إن الذي تقول وتدعو إليه لحسن، لو تُخبرنا أنّ لِما عملنا كفارةً! فنزل: {والذين لا يدعون مع الله إلها آخر، ولا يقتلون النفس التي حرم الله إلا بالحق، ولا يزنون} [الفرقان: 68]، ونزلت: {قل يا عبادي الذين أسرفوا على أنفسهم، لا تقنطوا من رحمة الله}."}, "67493": {"num": 67493, "aya": 53, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق عطاء- قال: بعث رسولُ الله صلى الله عليه وسلم إلى وحْشيّ بن حرب قاتل حمزة يدعوه إلى الإسلام، فأرسل إليه: يا محمد، كيف تدعوني وأنت تزعم أنّ مَن قتل أو أشرك أو زنى {يَلْقَ أثامًا يُضاعَفْ لَهُ العَذابُ يَوْمَ القِيامَةِ ويَخْلُدْ فِيهِ مُهانًا} [الفرقان: 68 - 69] وأنا صنعتُ ذلك فهل تجد لي مِن رخصة؟ فأنزل الله: {إلّا مَن تابَ وآمَنَ وعَمِلَ عَمَلًا صالِحًا فَأُولَئِكَ يُبَدِّلُ اللَّهُ سَيِّئاتِهِمْ حَسَناتٍ وكانَ اللَّهُ غَفُورًا رَحِيمًا} [الفرقان: 70]. فقال وحْشيّ: هذا شرط شديد؛ {إلّا مَن تابَ وآمَنَ وعَمِلَ عَمَلًا صالِحًا}، فلعلي لا أقدر على هذا. فأنزل الله: {إنَّ اللَّهَ لا يَغْفِرُ أنْ يُشْرَكَ بِهِ ويَغْفِرُ ما دُونَ ذَلِكَ لِمَن يَشاءُ} [النساء: 48]. فقال وحْشيّ: هذا أرى بعد مشيئة، فلا أدري يَغفر لي أم لا، فهل غير هذا؟ فأنزل الله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ} الآية. قال وحْشيّ: هذا نعم. فأسلم، فقال الناس: يا رسول الله، إنّا أصبنا ما أصاب وحْشيّ. قال: «هي للمسلمين عامة»."}, "67494": {"num": 67494, "aya": 53, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّهِ}، يقول: لا تيأسوا من رحمة الله، وذلك أن أهل مكة قالوا: يزعم محمدٌ أنّ مَن عبد الأوثان، ودعا مع الله إلهًا آخر، وقتل النفس التي حرّم الله، لم يُغفر له، فكيف نهاجر ونُسلم وقد عبدنا الآلهة، وقتلنا النفس التي حرّم الله، ونحن أهل الشرك؟! فأنزل الله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّهِ إنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا}."}, "67497": {"num": 67497, "aya": 53, "qail": "عطاء بن يسار", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن عطاء بن يسار -من طريق بعض أصحابه- قال: نزلت هذه الآيات الثلاث بالمدينة في وحْشيّ وأصحابه: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ} إلى قوله: {وأَنْتُمْ لا تَشْعُرُونَ}."}, "67500": {"num": 67500, "aya": 53, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: ذُكِر لنا: أنّ ناسًا أصابوا في الشِّرك عِظامًا، فكانوا يخافون أن لا يُغفَر لهم، فدعاهم الله بهذه الآية: {يا عِبادِيَ الَّذِينَ أسْرَفُوا} الآية."}, "67501": {"num": 67501, "aya": 53, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن إسماعيل السُّدّي -من طريق أسباط- في قوله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ}، قال: هؤلاء المشركون من أهل مكة. قالوا: كيف نُجيبك وأنت تزعُم أنّه مَن زنى، أو قتل، أو أشرك بالرحمن كان هالِكًا مِن أهل النار؟! فكل هذه الأعمال قد عملناها. فأُنزلت فيهم هذه الآية: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ}."}, "67504": {"num": 67504, "aya": 53, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّه} الآية، قال: كان قوم مسخوطين في أهل الجاهلية، فلما بعث الله نبيَّه قالوا: لو أتينا محمدًا صلى الله عليه وسلم، فآمنّا به، واتّبعناه. فقال بعضهم لبعض: كيف يقبلكم الله ورسولُه في دينه؟ فقالوا: ألا نبعثُ إلى رسول الله صلى الله عليه وسلم رجلًا! فلمّا بعثوا، نزل القرآن: {قل يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّه}، فقرأ حتى بلغ: {فَأَكُونَ مِنَ المُحْسِنِين}."}, "67506": {"num": 67506, "aya": 53, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس، في قوله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ} الآية، قال: قد دعا اللهُ إلى مغفرته مَن زعم أنّ المسيح هو الله، ومَن زعم أنّ المسيحَ ابنُ الله، ومَن زعم أنّ عُزيرًا ابن الله، ومَن زعم أنّ الله فقير، ومَن زعم أنّ يد الله مغلولة، ومَن زعم أن الله ثالث ثلاثة، يقول الله لهؤلاء: {أفَلا يَتُوبُونَ إلى اللَّهِ ويَسْتَغْفِرُونَهُ واللَّهُ غَفُورٌ رَحِيمٌ} [المائدة: 74]، ثم دعا إلى توبته مَن هو أعظم قولًا من هؤلاء؛ من قال: {أنا رَبُّكُمُ الأَعْلى} [النازعات: 24]، وقال: {ما عَلِمْتُ لَكُمْ مِن إلَهٍ غَيْرِي} [القصص: 38]. قال ابن عباس: مَن آيس العِباد مِن التوبة بعد هذا فقد جحد كتاب الله، ولكن لا يقدر العبدُ أن يتوب حتى يتوب الله عليه."}, "67507": {"num": 67507, "aya": 53, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجِيح- في قول الله: {الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ}، قال: قتْل النفس في الجاهلية."}, "67508": {"num": 67508, "aya": 53, "qail": "محمد بن كعب القرظي", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن محمد بن كعب القُرَظيّ -من طريق أبي صخر- أنه قال في هذه الآية: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّه}، قال: هي للناس أجمعين."}, "67509": {"num": 67509, "aya": 53, "qail": "زيد بن أسلم", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن زيد بن أسلم -من طريق أبي صخر- في قوله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّه}، قال: إنما هي للمشركين."}, "67511": {"num": 67511, "aya": 53, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّهِ}، يقول: لا تيأسوا من رحمة الله."}, "67518": {"num": 67518, "aya": 53, "qail": "عطاء بن يسار", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن عطاء بن يسار، قال: إنّ لِلمُقَنِّطين جسرًا؛ يطأُ الناسُ يومَ القيامة على أعناقهم."}, "67520": {"num": 67520, "aya": 53, "qail": "زيد بن أسلم", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن زيد بن أسلم: أنّ رجلًا كان في الأمم الماضية يجتهد في العبادة، ويُشَدِّد على نفسه، ويُقَنِّط الناس مِن رحمة الله، ثم مات، فقال: أي ربّ، ما لي عندك؟ قال: النار. قال: فأين عبادتي واجتهادي؟ فقيل له: كنت تُقَنِّط الناس مِن رحمتي، وأنا أقنِّطك اليوم من رحمتي."}, "67524": {"num": 67524, "aya": 53, "qail": "ابن عمر", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن ابن عمر: أنّ عمر بن الخطاب خرج ذات يوم إلى الناس، فقال: أيُّكم يخبرني بأعظم آية في القرآن، وأعدلها، وأخوفها، وأرجاها؟ فسكت القوم، فقال ابن مسعود: على الخبير سقطتَ؛ سمعتُ رسول الله صلى الله عليه وسلم يقول: «أعظم آية في القرآن: {الله لا إله إلا هو الحي القيوم} [البقرة: 255]. وأعدل آية في القرآن: {إن الله يأمر بالعدل والإحسان} إلى آخرها [النحل: 90]. وأخوف آية في القرآن: {فمن يعمل مثقال ذرة خيرا يره ومن يعمل مثقال ذرة شرا يره} [الزلزلة: 7 - 8]. وأرجى آية في القرآن: {قل يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله}»."}, "67529": {"num": 67529, "aya": 53, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن عامر الشعبي، قال: تجالسَ شُتَيْر بن شَكَل ومسروق، فقال شُتَيْر: إمّا أن تُحَدِّث ما سمعتَ مِن ابن مسعود فأصدّقك، وإمّا أن أحدِّث فتصدّقني. فقال مسروق: لا، بل حدِّث فأصدّقك. فقال: سمعتُ ابن مسعود يقول: إن أكبر آية فرحًا في القرآن: {يا عِبادِيَ الَّذِينَ أسْرَفُوا عَلى أنْفُسِهِمْ لا تَقْنَطُوا مِن رَحْمَةِ اللَّه}. فقال مسروق: صدقتَ."}, "67530": {"num": 67530, "aya": 53, "qail": "محمد بن سيرين", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن محمد بن سيرين، قال: قال عليٌّ: أيُّ آية أوسع؟ فجعلوا يذكرون آياتٍ مِن القرآن: {ومَن يَعْمَلْ سُوءًا أوْ يَظْلِمْ نَفْسَهُ} [النساء: 110]، ونحوها، فقال علي: ما في القرآن آية أوسع من: {يا عِبادِيَ الَّذِينَ أسْرَفُوا} الآية."}}, "n_athar": {"0": 10, "1": 1, "2": 4, "3": 17, "4": 1, "5": 11, "6": 29, "7": 13, "8": 11, "9": 21, "10": 25, "11": 2, "15": 7, "16": 3, "17": 13, "18": 9, "19": 3, "20": 4, "21": 9, "22": 16, "23": 32, "24": 5, "25": 1, "27": 1, "28": 7, "29": 20, "30": 4, "31": 19, "32": 2, "33": 20, "34": 1, "35": 2, "36": 11, "37": 1, "38": 2, "39": 2, "40": 1, "41": 4, "42": 16, "43": 3, "44": 2, "45": 7, "46": 3, "47": 1, "48": 3, "49": 8, "50": 2, "51": 2, "52": 1, "53": 48, "54": 8, "55": 3, "56": 16, "57": 2, "58": 3, "59": 5, "60": 3, "61": 6, "62": 2, "63": 15, "64": 3, "65": 1, "66": 1, "67": 36, "68": 53, "69": 16, "70": 3, "71": 10, "73": 21, "74": 11, "75": 8}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});